// Сгенерировано tools/build-base-media.mts: описания карточек справочника (TMDb), доля 10 из 16 по id
// (src/lib/shard.ts) — подгружается, когда раскрывают «Сюжет» (src/api, getPlot). Не править руками.
export const blurbs: Record<string, string> = {
 "f-wd165325": "В беременную наёмную убийцу по кличке Чёрная Мамба во время бракосочетания стреляет человек по имени Билл. Но голова у женщины оказалась крепкой — пролежав четыре года в коме, бывшая невеста приходит в себя. Она горит желанием найти предателей. Теперь только безжалостная месть успокоит сердце Чёрной Мамбы, и она начинает по очереди убивать членов банды Билла, решив оставить главаря напоследок.",
 "f-wd1741232": "Агент ЦРУ Итан Хант оказался в положении подозреваемого в предательстве «крота», из-за которого погибли несколько членов его команды, включая руководителя группы Джима Фелпса. В живых осталась еще только коллега Ханта — жена Фелпса агент Клэр. Чтобы снять с себя обвинения в предательстве, Ханту надо найти настоящего «крота». Для его приманки он решает похитить базу данных ЦРУ в Лэнгли.",
 "f-wd486239": "Адам и Гордон очнулись прикованными к трубам в огромном заброшенном помещении. Между ними труп в луже крови... Оба не понимают ни как они оказались в таком положении, ни как из него выйти. Достаточно быстро они осознают, что стали жертвой серийного маньяка, которого полицейские называют «Конструктор смерти» за его манеру ставить людей в ситуацию, где у них есть только два выхода — погибнуть самим или убить. На сей раз «изобретатель» поставил перед выбором Гордона: он должен убить Адама или его жена и дочь будут уничтожены. Расследовавший предыдущие «эксперименты» супер-изобретательного злодея детектив Тапп попытается вмешаться в ситуацию... Смогут ли Адам, Гордон и Тапп обыграть маньяка в его дьявольской игре и остаться в живых?",
 "f-wd1962112": "Это история Москвы начала пятидесятых, в которой компании молодых людей приходится бороться за право быть не такими как все, слушать другую музыку, по-другому одеваться и конечно же любить.",
 "f-wd1999930": "В южном городке орудует шайка валютчиков, возглавляемая Шефом и его помощником Графом (в быту — Геной Козодоевым). Скромный советский служащий и примерный семьянин Семен Семенович Горбунков отправляется в зарубежный круиз на теплоходе, где также плывет Граф, который должен забрать бриллианты в одном из восточных городов и провезти их в загипсованной руке. Но из-за недоразумения вместо жулика на условленном месте падает ничего не подозревающий Семен Семенович, и драгоценный гипс накладывают ему.",
 "f-wd27188178": "Молодой воришка по имени Аладдин хочет стать принцем, чтобы жениться на принцессе Жасмин. Тем временем визирь Аграбы Джафар, намеревается захватить власть над Аграбой, а для этого он стремится заполучить волшебную лампу, хранящуюся в пещере чудес, доступ к которой разрешен лишь тому, кого называют \"алмаз неограненный\", и этим человеком является никто иной как сам Аладдин.",
 "f-wd18604504": "Правительство решает дать команде суперзлодеев шанс на искупление. Подвох в том, что их отправляют на миссию, где они, вероятнее всего, погибнут...",
 "f-wd20962283": "В системе космического корабля, перевозящего колонистов на далёкую планету, происходит сбой. В результате главный герой выходит из гиперсна на 90 лет раньше положенного срока. Оставшись с перспективой стареть и умирать в одиночестве, он будит прекрасную девушку, которой такой расклад, само собой, придётся не по душе...",
 "f-wd18199330": "Фильм рассказывает о приключениях писателя Ньюта Саламандера в Нью-Йоркском секретном обществе волшебниц и волшебников, происходивших за 70 лет до того, как Гарри Поттер прочитает книгу этого писателя в школе.",
 "f-wd13099455": "Главный герой - подросток Томас, который просыпается в лифте, но ничего не помнит, кроме своего имени. Он оказывается среди 60 подростков, научившихся выживать в замкнутом пространстве. Раз в 30 дней прибывает новый мальчик. Группа ребят проживает в «Приюте» уже два года. Они кормятся тем, что удается вырастить на земле, и пытаются найти выход из лабиринта, окружающего их место жительства. Когда герои уже начинают терять надежду, появляется девочка в состоянии комы, но со странной запиской. Мир героев начинает меняться.",
 "f-wd777739": "Инженер-изобретатель Тимофеев сконструировал машину времени, которая соединила его квартиру с далёким шестнадцатым веком - точнее, с палатами государя Ивана Грозного. Туда-то и попадают тёзка царя пенсионер-общественник Иван Васильевич Бунша и квартирный вор Жорж Милославский. На их место в двадцатом веке «переселяется» великий государь. Поломка машины приводит ко множеству неожиданных и забавных событий...",
 "f-wd244019": "В основу сюжета положена волшебная сказка Вильгельма Гауфа. Для того чтобы осуществить свои коварные планы, злой колдунье нужен ребёнок с очень добрым сердцем. Обманом она заманивает к себе маленького Якоба — сына сапожника и зеленщицы. Когда Якоб отказывается участвовать в её сомнительных делах, ведьма превращает его в уродливого карлика. Но вечная сила любви и дружбы помогает героям сказки рассеять злые чары…",
 "f-wd4985891": "В недалёком будущем мутанты близки к истреблению роботами-охотниками на мутантов Стражами. Единственная надежда для мутантов выжить - предотвратить череду роковых событий, приведших к появлению Стражей. С помощью своих способностей, Китти Прайд перемещает сознание Росомахи в его молодое тело в 1973 год. В прошлом всё оказывается не так радужно: молодой Профессор Икс окончательно разочарован в своих идеях, Магнето содержится в тюрьме глубоко под землёй, а человечество не знает как реагировать на широкое появление мутантов...",
 "f-wd115175910": "В американском городе Новый Рим архитектор Цезарь Катилина — умеющий останавливать время лауреат Нобелевской премии и глава дизайнерского бюро — проектирует идеальный мегаполис будущего, где все будут счастливы. Построить его он планирует с помощью им самим же изобретённого волшебного материала мегалона. Против такого подхода и самого Цезаря активно выступает мэр Цицерон, зато мэрская дочь Джулия сначала увлекается проектами Катилины, а потом и им самим.",
 "f-wd517265": "На балу во дворце Капулетти зарождается любовь двух юных существ, судьбою обреченных на ненависть. Ромео Монтекки и Джульетта Капулетти полюбили друг друга на свою беду, ведь их семьи ведут смертельную вражду уже многие, многие годы… Но их любовь сильнее родовой вражды, сильнее предрассудков и непреодолимых препятствий. Великая сила этой любви побеждает все, даже смерть…",
 "f-wd659671": "1984 год. Майкл Джексон — король даже в забытом богом местечке Уаихао Бэй, что в Новой Зеландии. 11-летний Аламейн, которого все зовут просто Мальчик, живет на ферме с бабушкой, козлом и младшим братом Рокки, считающем, что обладает магической силой. В один прекрасный день объявляется отец Мальчика, о котором парень всем вокруг рассказывал героические небылицы. Но на деле папаша оказывается придурковатым неудачником, вернувшимся только за тем, чтобы найти закопанный несколько лет назад мешок с деньгами…",
 "f-wd123928072": "Квалифицированный адвокат Рита работает в крупной мексиканской компании, которая больше заинтересована в отмывании денег от преступников, чем в служении правосудию. Неожиданно Рита получает интригующее предложение, от которого трудно отказаться. Грозный босс картеля, Хуан Дель Монте, хочет выйти из своего криминального бизнеса и исчезнуть навсегда, для чего он решил сменить пол. Именно Рита должна ему помочь.",
 "f-wd777629": "Главный герой Расти Сэбич - окружной прокурор, который за долгие годы своей карьеры привык выступать лишь в роли обвинителя. Неожиданно его начальник поручает ему провести срочное расследование убийства сотрудницы прокуратуры. Но дело осложняется тем, что погибшая, привлекательная молодая блондинка Каролин Полимус, была любовницей Сэбича, и, в конце концов, подозрение в её убийстве падает на него. Затевается шумный судебный процесс, и Расти обращается к очень дорогому адвокату...",
 "f-wd18031184": "Сюжет фильма основан на реальных событиях, произошедших в 1952 году, когда сотрудники береговой охраны в самый разгар шторма, используя деревянные моторные лодки, пытались спасти экипаж двух нефтяных танкеров.",
 "f-wd73537113": "Радиожурналист Джонни отправляется с 9-летним племянником в поездку по Америке. Совместное путешествие навсегда изменит каждого из них.",
 "f-wd18192306": "Профессор Роберт Лэнгдон приходит в сознание в одной из итальянских больниц, полностью потеряв память. Местный врач Сиенна Брукс пытается помочь Роберту не только восстановить воспоминания, но и остановить загадочных злоумышленников, которые намерены распространить смертоносный вирус.",
 "f-wd196004": "Спасаясь от полиции после ограбления банка, два брата — грабителя берут в заложники священника и его детей. Около американской границы они решают провести ночь в придорожном баре. Тут-то всё и начинается…",
 "f-wd60834962": "Наследник знаменитого дома Атрейдесов Пол отправляется вместе с семьей на одну из самых опасных планет во Вселенной — Арракис. Здесь нет ничего, кроме песка, палящего солнца, гигантских чудовищ и основной причины межгалактических конфликтов — невероятно ценного ресурса, который называется меланж. В результате захвата власти Пол вынужден бежать и скрываться, и это становится началом его эпического путешествия. Враждебный мир Арракиса приготовил для него множество тяжелых испытаний, но только тот, кто готов взглянуть в глаза своему страху, достоин стать избранным.",
 "f-wd26465665": "Группа исследователей с международного космического корабля обнаруживает жизнь на Марсе. Они еще не подозревают, какие события повлечет за собой их открытие.",
 "f-wd27965092": "Английский путешественник Джонатан Грин получает от Петра Первого заказ на изготовление карт Дальнего Востока России. Ему вновь предстоит долгий путь, полный невероятных приключений, который приведет его в Китай. Картограф столкнется с массой головокружительных открытий, неожиданных встреч с диковинными существами, китайскими принцессами, мастерами смертоносных боевых искусств и самим Лун-Ван, Царем всех драконов. Что может быть опаснее, чем посмотреть в глаза Вию? Разве что встретиться с ним вновь. Что на этот раз окажется сильнее — непоколебимый скептицизм ученого или древняя черная магия, уже давно захватившая власть в Восточных землях?",
 "f-wd21528112": "Агент Лоррейн Бротон, бриллиант в короне Секретной разведывательной службы Её Величества, не просто мастер шпионажа: она бомбически сексуальна, взрывоопасна и использует весь арсенал своих уникальных умений во время невыполнимых миссий. В неспокойном Берлине, куда её направляют с заданием вернуть бесценное досье, она вынуждена объединиться с агентом под прикрытием, Дэвидом Персивалем. Вместе им предстоит проложить путь через тернии смертельных шпионских игр.",
 "f-wd1066948": "2029 год. Благодаря значительным достижениям в кибернетике люди могут заменять свои конечности роботизированными частями. Майор Мотоко Кусанаги из 9-го отдела службы безопасности ведёт расследование, связанное с таинственным хакером, который называет себя Кукловод.",
 "f-wd81205": "Мегамозг — самый гениальный и самый неудачливый злодей в мире. Вот уже много лет он пытается покорить Метро-Сити самыми разнообразными способами. Но каждая такая попытка кончается провалом по вине супергероя по имени Метро-Мэн. Но злодей убивает супергероя, и внезапно Мегамозг лишается цели в жизни. Суперзлодей без супергероя. Единственный выход — создать нового супергероя, которого он называет Титаном. Но Титан решает, что быть злодеем куда интереснее.",
 "f-wd33665391": "Мастер перевоплощений Саня по прозвищу Трансформер провернул кучу афер, точь-в-точь изображая десятки персонажей. Но в этот раз он украл не у тех… Теперь у парня на хвосте очень плохие люди с пистолетами. Саня решает залечь на дно в доме престарелых в образе пожилой тети. И когда ему казалось, что он попал в безвыходную ситуацию, новый поворот судьбы дарит ему любовь и надежду превратиться в приличного человека.",
 "f-wd28999515": "Прошли тысячелетия после того, как мир настиг апокалипсис. Человечество адаптировалось и теперь живет по новым правилам. Гигантские движущиеся мегаполисы рассекают пустоши и поглощают маленькие города ради ресурсов. Том Нэтсуорти из нижнего уровня великого Лондона оказывается в смертельной опасности, когда на его пути появляется скрывающаяся от закона бунтарка Эстер Шоу. Они не должны были встретиться, но им суждено изменить будущее.",
 "f-wd6151665": "Автоботы и десептиконы покинули планету, оставив человечество собирать её по кусочкам. Между тем группа могущественных бизнесменов и гениальных учёных пытается извлечь уроки из ошибок прошлого и улучшить технологии до такой степени, чтобы выйти за пределы контролируемого ранее. В это время другая группа - древних мощных трансформеров - берет Землю под прицел.",
 "f-wd55102449": "Семья Луиса Крида переезжает в сельский дом, который, как выясняется, расположен по соседству с мрачным Кладбищем домашних животных. Именно здесь Луис хоронит кошку, любимицу семьи, погибшую под колесами грузовика. Эта смерть влечет за собой череду чудовищных событий, которые доказывают Кридам, что мертвые должны оставаться мертвыми…",
 "f-wd388944": "Затерявшись в лесах Западной Вирджинии в результате рокового стечения обстоятельств, группа молодых людей пытается добраться до ближайшего телефона. Но вместо телефона им суждено найти дом в горах, увешанный страшным оружием и отвратительными трофеями… Кто, или что живет в этом доме? Молодые люди начинают понимать, что все их злоключения — способ загнать дичь в ловушку, где они — это дичь, а зловещие охотники — обитатели дома…",
 "f-wd180098": "Иерусалим, 26 год нашей эры. Два друга детства, иудей Бен-Гур и римский трибун Мессала, встречаются после долгой разлуки взрослыми людьми. Мессала просит назвать самых ярых противников власти Рима, но Бен-Гур не может предать собственный народ и отказывается, что приводит к конфликту. Вскоре Мессала, воспользовавшись обстоятельствами, решает отомстить бывшему другу и укрепить свою власть. По надуманному обвинению он бросает в тюрьму мать и сестру Бен-Гура, а его самого отправляет на галеры.",
 "f-wd19614711": "Используя инопланетные технологии, жители Земли создали специальную программу по защите планеты. Но ничего не может нас спасти от нового, еще более разрушительного и масштабного инопланетного вторжения — только смелость нескольких героев, которые единственные могут спасти наш мир от уничтожения.",
 "f-wd1051702": "В конце Второй Мировой войны молодой военный по имени Стив Роджерс стал частью эксперимента, благодаря которому США надеялись подавить последние очаги сопротивления нацистов на втором фронте. Результатом эксперимента стал сверхчеловек, «Капитан Америка», оставшийся Стивом Роджерсом лишь в повседневной жизни.",
 "f-wd21512706": "Проблемный охранник начинает работать в пиццерии «У Фредди Фазбера». Проводя свою первую ночь на работе, он понимает, что ночную смену в «Фредди» будет не так-то просто выдержать.",
 "f-wd125622088": "Кот просыпается в мире, погруженном в воду, где не осталось людей. Ему удается найти убежище на лодке вместе с другими животными, однако ужиться с ними оказывается ещё сложнее, чем преодолеть свой страх воды. Но каждому предстоит научиться жить с теми, кто отличается от них, и адаптироваться к новому дивному миру.",
 "f-wd113630174": "Ремейк одноимённого фильма 1989 года. Бывший боец UFC Элвуд Далтон переживает не лучшие времена. Он живёт в машине и зарабатывает участием в подпольных боях без правил. Владелица бара «Дом у дороги», который расположен во Флорида-Кис, предлагает Далтону работу вышибалы, поскольку в заведении стабильно устраивают погромы члены местной банды.",
 "f-wd120514821": "В далёком городе живёт девочка Элли. Однажды злая колдунья Гингема наколдовала ураган, который унёс Элли и её собачку Тотошку в страну Жевунов. Чтобы вернуться домой, Элли вместе с друзьями - Страшилой, Железным Дровосеком и Трусливым Львом - отправляются по жёлтой кирпичной дороге в Изумрудный город на поиски Волшебника, который исполнит их заветные желания",
 "f-wd112183404": "Приквел, подробно рассказывающий о происхождении существ из «Тихое место».",
 "f-wd124256460": "Организатор охоты за сокровищами собирает команду для судьбоносного приключения. Но чтобы обойти угрозы, поджидающие на каждом шагу, ему нужна та, кто ещё умнее: его отчуждённая сестра.",
 "f-wd112801489": "В Элемент-Сити обитатели огня, воды, земли и воздуха живут вместе. У сильной и вспыльчивой Эмбер завязывается дружба с расслабленным, плывущим по течению Уэйдом — дружба, которая бросит вызов её представлениям о мире вокруг.",
 "f-wd215518": "В славном городе Аграба живёт Аладдин, весёлый воришка с золотым сердцем. Живёт и не знает, что вскоре его ждет величайшее приключение в жизни. Ведь только с его помощью чёрный маг Джафар может овладеть невероятным сокровищем — лампой, в которой заключён исполняющий желания могущественный Джинн. И только хитроумие, смекалка и доброта Аладдина способны помешать Джафару завладеть лампой и захватить власть над миром.",
 "f-wd165512": "История поиска и спасения щенят далматинских догов, которые были похищены у своих хозяев по приказу злобной фурии, Стервеллы Де Виль. Алчная модница задумала сшить себе пятнистый меховой наряд из шкурок бедных малюток. Однако животные, объединившись, ухитряются проучить ее.",
 "f-wd215617": "Давным-давно в далекой стране жили король с королевой. Когда у них родилась долгожданная дочь Аврора, в королевстве был устроен большой праздник, чтобы все могли поприветствовать малютку. На бал пригласили и трех добрых фей — Флору, Фауну и Хорошую Погоду, а про злую колдунью Мэлифисент забыли.  Оскорбленная, она наложила на принцессу проклятье — в день своего 16-летия Аврора уколется о веретено и уснет вечным сном. Колдовство оказалось таким сильным, что добрые феи не смогли разрушить его. Но все же они спасли принцессу: она очнется ото сна после поцелуя прекрасного принца…",
 "f-wd42051": "Идёт третий год Войн клонов. Галактическая Республика, некогда бывшая спокойным и гармоничным государством, превратилась в поле битвы между армиями клонов, возглавляемых канцлером Палпатином, и армадами дроидов, которых ведёт граф Дуку, тёмный лорд ситхов. Республика медленно погружается во тьму. Лишь рыцари-джедаи, защитники мира и справедливости, могут противостоять злу, которое вскоре поглотит галактику. Но настоящая битва идёт в душе у молодого рыцаря-джедая Энакина, который разрывается между долгом джедая и любовью к своей жене, сенатору Падме Амидале. И от того, какое чувство в нём победит, зависит будущее всего мира.",
 "f-wd13091172": "Действие развивается в японском городе Сан-Франсокио, где мальчик-гений и его робот-телохранитель присоединяются к команде неопытных супергероев.",
 "f-wd271189": "Аид — властитель загробного мира. Много лет назад он был фактически сослан своим старшим братом Зевсом в глубины Ада и теперь намерен наверстать упущенное, собрав армию монстров и захватив Олимп. Единственный, кто может помешать Аиду — сын Зевса, юный Геркулес, поэтому прислужники злодея похищают младенца и превращают его в простого смертного. Спустя много лет юноша узнает о своем происхождении и ставит целью вернуться домой, но для этого ему придется совершить немало подвигов и стать настоящим героем. Но, как выясняется, даже победы над силами зла недостаточно, чтобы вернуть божественное начало...",
 "f-wd208572": "Лидер местной банды скинхэдов Дерек Виньярд прочно удерживает авторитет в своем районе. Убежденный в своей правоте, он беспощадно расправляется с теми, кто имеет не белый цвет кожи. Независимость и смелость Дерека вызывают восхищение у его младшего брата Дэнни, который уже тоже сделал свой выбор. Но зверское убийство двух чернокожих парней, совершенное Дереком, разделяет дороги братьев: Дерек оказывается в тюрьме, где существует свой расклад сил, а Дэнни на свободе успешно продолжает дело брата. До тех пор, пока их пути не пересеклись вновь...",
 "f-wd322328": "Мультфильм рассказывает о царстве Хэллоуин, царстве страхов и кошмаров, где живут мертвецы, уродцы, чудовища во главе с царем ужасов Джеком Скелингтоном. Под рождество Джек случайно попадает в город Рождества, где узнает, что есть где-то радость, добро и веселье.Ему страшно захотелось испытать это чувство — дарить людям счастье — и он похитил Сэнди Клауса и занял его место. Результаты были, правда, самые плачевные, да и подарки его никому, мягко говоря, не понравились. Но он все понял и исправил свою ошибку.",
 "f-wd213208": "Шон Босуэлл — одинокий парень, который хочет казаться профи уличных гонок. Он бесшабашно гоняется по улицам города, пытаясь убежать от жизненных невзгод и наживая себе врагов среди местных властей. Когда Шону грозит тюрьма, его от греха подальше отсылают к отцу — профессиональному военному, который служит на военной базе в Японии.В незнакомой стране, живущей по своим законам, Шон чувствует себя еще большим изгоем. Однако вскоре его американский приятель Твинки знакомит его с миром подпольного дрифт-рейсинга. Раньше Шон просто тупо гонялся по улицам, а здесь перед ним открылся целый мир своеобразного искусства из металла и резины, дороги которого оказались невообразимо круты на поворотах…",
 "f-wd169082": "Строгий отец поставил условие: Бьянка пойдет на свидание, если ее сестра Кэт тоже согласится встретиться с парнем. Но Кэт — синий чулок и отчаянная мужененавистница. Бьянка пытается найти для сестры такого же зануду, как она.",
 "f-wd392530": "16-летний Джим Хоукинс отправляется на поиски таинственной Планеты Сокровищ в компании настоящих космических пиратов. Под руководством корабельного кока, киборга Джона Сильвера, он становится умелым «космоплавателем» и не раз спасает космический галеон от самых серьезных опасностей: черных дыр, взрывов сверхновых и космических штормов.",
 "f-wd1102220": "Палеонтолог Алан Грант, принимает предложение состоятельного предпринимателя совершить обзорную экскурсию над печально знаменитым островом Сорна на специально нанятом самолёте. Мог ли доктор Грант предполагать, что страшная, непредвиденная катастрофа снова заставит его столкнуться со свирепыми плотоядными существами из прошлого?",
 "f-wd193573": "Действие фильма разворачивается в 1899 году в знаменитом парижском ночном клубе Мулен Руж. Это не только дискотека и шикарный бордель, но и место, где, повинуясь неудержимому желанию прочувствовать атмосферу праздника, собираются страждущие приобщиться к красоте, свободе, любви и готовые платить за это… наличными. Это место, где воедино сходятся трагедия и комедия, роскошные интерьеры начала столетия и современные музыкальные ритмы.",
 "f-wd223559": "История лучника армии Ричарда Львиное Сердце, который борется против нормандских захватчиков и становится легендарным героем, известным под именем Робин Гуд.",
 "f-wd483852": "Неприятности сыплются на Дэниеля Хиларда, как из рога изобилия: он теряет работу, от него уходит жена и после развода ему позволено видеть детей всего раз в неделю!  Но Дэниель находит выход — переодевается в женское платье и становится Миссис Даутфайр — пожилой женщиной. Он нанимается к собственной жене в домработницы, и теперь может видеть своих детей каждый день. Последствия, естественно, будут самыми непредсказуемыми.",
 "f-wd244448": "Угледобывающий район в Южном Уэльсе, тяжелый труд шахтеров, жизнь их семей увидены глазами Хью, младшего из шести детей семьи во главе с суровым отцом и любящей матерью.",
 "f-wd155018": "1327 год. В обществе молодого послушника Адсо францисканский монах Вильям Баскервильский расследует серию трагических смертей монахов в бенедиктинском монастыре на севере Италии.  За всеми этими смертями кроется страшная тайна, и вскоре Вильям убеждается, что ключ к раскрытию загадки лежит в обнаружении сурово охраняемого древнего манускрипта, который хранится в тайной библиотеке монастыря…",
 "f-wd272036": "Два молодых человека Джек Пауэлл и Дэвид Армстронг из одного небольшого городка влюблены в Сильвию Льюис. Однако Сильвия отвечает взаимностью Дэвиду, а Джек не замечает влюбленную в него соседскую девчонку Мэри Престон. После вступления США в Первую Мировую войну юноши попадают в авиационный корпус и становятся не только асами, но и друзьями.\r Стараясь быть ближе к Джеку, Мэри присоединяется к женскому механизированному корпусу, но война охватила большие расстояния и они почти не встречаются. Один единственный раз Мэри находит Джека в увольнении, но в таком виде, что он ее не узнает и встреча печально заканчивается для самой Мэри. Меж тем, между друзьями произошла размолвка, и они улетают в бой, не примирившись, что в итоге приводит к трагической развязке — это война…",
 "f-wd18844656": "Что делают домашние животные пока хозяева пропадают на работе? С тоской смотрят в окно? Смиренно дремлют на коврике у двери? Как бы не так. Они ведут свою тайную жизнь.",
 "f-wd3286391": "Кантри-музыкант Джексон Мейн, чья карьера быстро катится под откос, однажды знакомится с никому не известной талантливой певицей Элли. Между героями вспыхивает страстный роман. Джек помогает Элли добиться успеха. Но чем стремительнее набирает обороты музыкальная карьера Элли, тем сложнее ему мириться со своей увядающей славой.",
 "f-wd277080": "Бывший секретный агент американских спецслужб, ушедший в отставку, чтобы быть ближе к своей дочери, с матерью которой он в разводе, узнаёт, что его дочь похитили в Париже, куда та отправилась со своей подругой. Узнав по старым связям, что у него есть всего четверо суток (96 часов), он решает не обращаться в полицию, а спасти дочь собственными силами...",
 "f-wd329709": "Английский флот XVIII века отличался жесткой (даже жестокой) дисциплиной. Малейшие провинности наказывались плетьми, более тяжелые проступки карались смертной казнью. Доведенные до отчаяния матросы поднимали бунты и пытались освободиться от гнета.\r 1789 год. Экипаж британского корабля «Баунти» под руководством жестокого капитана Блая наполнив трюмы, отчаливает от берегов Таити. До этого дня в течение шести месяцев команда корабля подвергалась физическим и моральным издевательствам со стороны капитана и его приспешников.\r Изнурительная работа и отсутствие пищи вынуждают моряков поднять бунт. Зачинщиком мятежа становится матрос, аристократ Кристиан Флетчер. Ссадив с корабля капитана и преданных ему людей, «Баунти» взял курс обратно на Таити, именно там Флетчер и другие мятежники решили провести всю оставшуюся жизнь…",
 "f-wd97288428": "Мир еще не видел столь искусных авантюристов: ловкий карманник Мистер Волк, опытный взломщик сейфов Мистер Змей, хладнокровный мастер маскировки Мистер Акула, вспыльчивый и мускулистый Мистер Пиранья, а также остроумная хакер высшего класса Мисс Тарантула. Однако даже самые умные преступники иногда допускают ошибки. Чтобы спастись от неминуемый тюрьмы, главарь банды Мистер Волк вынужден идти на крайние меры: «Плохие парни» должны измениться в лучшую сторону. Или сделать вид? Но когда новый злодей угрожает городу, сможет ли Мистер Волк убедить остальных действительно стать… хорошими ребятами?",
 "f-wd273686": "Главный герой — богатый гавайский землевладелец. Он вместе с двумя дочерьми предпринимает попытку найти любовника жены, искренне веря, что таким образом спасет семейный очаг.",
 "f-wd159638": "Мир вампиров в ужасе от появления новой расы суперкровососов. Именно благодаря этому легендарный Блэйд и его учитель Уистлер вынуждены объединиться со своими кровными врагами - Кровавой Стаей, элитным отрядом вампиров-воинов.",
 "f-wd465009": "В прошлом безымянный странник был «Марьячи» – бродячим мексиканским музыкантом, выступавшим на похоронах и свадьбах. Но бандиты убили его возлюбленную и прострелили ему руку, лишив возможности играть на гитаре. Тогда Марьячи переключился на музыку пистолетных выстрелов и автоматных очередей. Теперь он бродит по Мексике и мстит тем, кто отнял у него любовь и гитару.",
 "f-wd399823": "Айова, 1960-е. Франческа Джонсон родом из Италии, но теперь она — жена американского фермера и мать двоих детей. Однажды, когда муж и дети уезжают на ярмарку в другой штат, Франческа встречает приезжего одинокого фотографа Роберта Кинкейда, который на несколько дней приехал в округ Мэдисон по заданию журнала National Geographic, чтобы сделать снимки местных старых деревянных мостов. В сердцах Франчески и Роберта вспыхивает сильное чувство, но на любовь, о которой они мечтали всю жизнь, им отпущено лишь 4 дня.",
 "f-wd15524911": "Дэйв — фантастически талантливый журналист популярного ток-шоу, продюсирует которое его лучший друг Аарон. Друзья, давно мечтавшие сделать что-то по-настоящему значимое, решают взять интервью у северокорейского диктатора Ким Чен Ына. Вскоре к ним обращается ЦРУ, которое просит наших героев ни много ни мало — убить Кима. Так начинается веселая история о двух наименее квалифицированных наемных убийцах в истории человечества…",
 "f-wd7731172": "Человечество случайно разбудило гигантское древнее существо, что повлекло за собой ужасающие последствия…",
 "f-wd753605": "Пасхальный кролик Хэппи не хотел заниматься семейным делом - в преддверии Пасхи разносить детишкам подарки. Он всегда мечтал стать барабанщиком и прославиться на весь мир. Однажды кролик сбегает с родного волшебного острова и отправляется в Голливуд, чтобы стать звездой. Однако вместо этого, он попадает под машину Фрэда. Теперь, парню предстоит из-за случившегося, временно взять на себя обязанности Хэппи. Впереди Фрэда и Хэппи ждёт море увлекательных приключений и смешных ситуаций.",
 "f-wd458629": "Чем должен увлекаться сын шахтера? Сомнений нет: боксом и только боксом. Но у 11-летнего Билли Эллиота на этот счет было свое мнение. Он был влюблен в… балет.  Отец и старший брат Тони впадают в ярость, когда узнают, что он «променял бокс» на менее «мужественный балет». И только острая на язык миссис Уилкинсон поддерживает Билли в его желании танцевать, и он получает шанс поступить в Королевскую балетную школу.",
 "f-wd23395": "Два приятеля едут в Лас-Вегас. Спортивный обозреватель Рауль Дьюк едет, чтобы осветить знаменитую «Минт 400». Его спутника зовут Доктор Гонзо, и он адвокат. Обзор «Минт 400» из-за непогоды и отсутствия интереса у рецензента оборачивается полным провалом, и Дьюк и Гонзо отправляются в казино.",
 "f-wd464536": "Картина снята по мотивам произведений М. Горького. В основе - несколько пересекающихся историй любви. Действие разворачивается внутри цыганского табора, блуждающего по степям Бессарабии, на окраине Австро-Венгерской империи.",
 "f-wd2198716": "Нужда приводит деревенского парня на завод, а участие в бунте — в тюрьму. Суровая школа тюрьмы и окопной жизни, общение с революционерами-большевиками открывают глаза бывшему крестьянину — и он в первых рядах солдат и рабочих идет на штурм Зимнего дворца.",
 "f-wd1764277": "По мотивам одной из самых известных повестей Николая Гоголя «Тарас Бульба». События «Запорожской сечи» отсылают к тяжелому периоду в истории казачества, когда запорожцы поднялись на борьбу с Речью Посполитой.В самом центре политических интриг оказалась семья уважаемого казака Тараса Бульбы, переживающего глубокую личную драму. Его сын Андрий полюбил польскую аристократку и хочет бежать из Сечи. Раздираемый чувством и долгом Тарас объявляет сыну последнюю родительскую волю…",
 "f-wd1877764": "Музыкальная комедия о похождениях жизнерадостного пастуха-музыканта Кости Потехина, которого приняли за модного заграничного гастролера. В одесском мюзик-холле простодушный Костя произвел сенсацию и стал дирижером джаз-оркестра. Его оркестр готовится к выступлению на сцене Большого театра, а вместо репетиций играет на похоронах…",
 "f-wd2471725": "Историко-революционный фильм о деятельности Ленина в первые годы Советской власти.",
 "f-wd339708": "Дмитрий Дмитриевич Гуров рано женился, жену не любит, детьми скорее тяготится. Он не упускает случая завести роман на стороне. На отдыхе в Ялте он обращает внимание на даму, прогуливающуюся по набережной с собачкой. Она молода, из хорошего общества, замужем; она замкнута и ни с кем не знакомится. Гурову удается заинтересовать даму, развеселить её и узнать, что её зовут Анной Сергеевной. Ему кажется, что в ней есть что-то «жалкое».",
 "f-wd1976863": "В середине 30-х годов цирковая актриса - Марион Диксон - бежит из США с маленьким чернокожим сыном. Зная факты ее личной жизни, цирковой артист фон Кнейшиц шантажирует и эксплуатирует ее. Приехав с оригинальным аттракционом в СССР, она находит здесь друзей и решает остаться навсегда.",
 "f-wd2445353": "По палящим пескам среднеазиатской пустыни движется, преследуемый белыми, умирая от жажды, отряд красноармейцев во главе с комиссаром Евсюковым. На боевом счету у лучшего стрелка отряда Марютки — сорок убитых белогвардейцев. В последнем бою по захвату каравана взят в плен белый поручик-аристократ Говоруха-Отрок, направленный с дипломатической миссией от Колчака к Деникину.  Марютке поручают конвоировать пленного....",
 "f-wd2394071": "Летчик-испытатель Астахов, герой Советского Союза, во время войны попадает в плен. После войны вернувшегося Астахова исключают из партии, увольняют с работы и лишают правительственной награды. Долгие годы герой не имеет возможности вернуться к своей профессии. Астахов спивается, но любовь Саши и вера в себя спасают его и возвращают надежду на справедливость...",
 "f-wd3007695": "У Гоголя Акакий Акакиевич уже родился маленьким старичком и с первой минуты испытывал страх перед жизнью. Герой ФЭКСов молод, полон надежд, его душа открыта миру. Маленький чиновник безнадежно вздыхает о прекрасной Незнакомке, являющейся ему на Невском в ореоле искрящихся снежинок.",
 "f-wd1895210": "На планету Венера отправляется первая советская космическая экспедиция из трех кораблей. При подходе к Венере один из кораблей гибнет. Экипажи двух других кораблей, среди которых находятся иностранец и робот «железный Джон», благополучно совершают посадку. Две группы движутся по направлению друг к другу. При этом на орбите остается один корабль с космонавтом на борту. Прежде чем герои найдут друг друга и улетят на Землю, их застигнет извержение вулкана, они погрузятся на морское дно, встретят неведомых животных и достойно перенесут все психологические проблемы малых коллективов в экстремальных ситуациях.",
 "f-wd4427861": "Всего одна ночь с незнакомкой становится для главного героя настоящим наваждением. Этот «солнечный удар» не отпускает его даже в самые «окаянные дни» гибели Российской Империи...",
 "f-wd677628": "Потерпевших кораблекрушение в Каспийском море Алексея и Юсуфа спасли рыбаки с ближайшего острова, после чего друзья вступили в бригаду рыболовецкого колхоза «Огни коммунизма», влюбившись в молодую рыбачку Машеньку...",
 "f-wd425937": "Приехав по срочному вызову в отель, инспектор полиции не обнаружил ничего уголовнонаказуемого, но подметил происходящие там странности. Снежная лавина не позволила ему уехать в тот же день, и вскоре инспектор обнаружил тело убитого постояльца. Подозрение падает на всех, кто живет в отеле.",
 "f-wd388339": "Первый фильм историко-революционной трилогии о Максиме, ставшем профессиональным революционером.",
 "f-wd17605759": "Во многих деревнях России из-за их удаленности от городов и бездорожья люди живут как бы вне государства. В таких местах они практически предоставлены сами себе. Зачастую единственным представителем государства в подобных краях становится почтальон. Он — главное связующее звено между немногочисленными жителями заброшенных деревень и цивилизацией. Один из таких почтальонов станет главным героем картины.",
 "f-wd1219788": "Закончилась у солдата служба, спешит солдат домой. Но по пути в родные места довелось ему сделать еще одно доброе дело: помочь мальчику Иванушке вызволить из плена матушку свою — Марью-Искусницу.  Уж как ни старался могущественный и хитрый царь Водокрут совсей своей придворной нечистью, так и не смог побороть солдатскую смекалку и доброе сердце…",
 "f-wd1971187": "Далекое будущее. Земной звездолёт «Тантра» попал в гравитационное поле неизвестной железной звезды. Топливо на исходе, и путешественники не в силах вырваться из её гравитационного поля. Они вынуждены либо оставаться на орбите еще двадцать лет, либо совершить посадку на неизвестную планету, на которой обнаружен инопланетный звездолет… Земляне рассчитывают пополнить запасы топлива на чужом звездолёте и вернуться домой…  Фильм продолжительностью 75 минут был снят в 1967 г. по одноимённому роману Ивана Ефремова.  Рабочее название «Туманность Андромеды. Часть 1. Пленники железной звезды». Считается, что планировали снять вторую часть. Однако, смонтирован он так, что события, показанные в конце фильма совпадает с окончанием романа.  В 1980 г. была выпущена отреставрированная версия фильма продолжительностью 68 мину. Из неё были вырезаны или переозвучены все упоминания о «светлом коммунистическом будущем».",
 "f-wd4439873": "12-летний московский школьник Волька, купаясь в Москва-реке, находит какой-то древний запечатанный сосуд. Мальчишеское любопытство настолько сильно, что при первом же удобном случае Волька вскрывает его, и из сосуда появляется сказочный джинн - Гассан Абдурахман ибн Хоттаб.За то, что Волька спас его от двухтысячелетнего заточения, джинн, прозванный мальчиком Хоттабычем, становится его верным слугой. Он пытается задарить мальчика, пригнав к его дому целый караван верблюдов с несметными сокровищами. Вместе они совершат увлекательный полет в Индию на волшебном ковре-самолете...",
 "f-wd15966847": "Модный столичный ресторан «Клод Моне» процветает. Именно здесь, в родном заведении Вика и Максим хотят отпраздновать долгожданную свадьбу. Но планы меняются, когда в ресторане назначают переговоры Президентов России и Франции! Команда ресторана терпит фиаско и вынуждена отправиться в «изгнание» — в Париж. Там Шеф с Максом сталкиваются с опасными конкурентами: Шеф — с ближайшим родственником, а Максим — с красавцем Николя, который кружит Вике голову не хуже искристого шампанского! И это еще не все вызовы, которые бросает им «Город любви», ведь надо постараться спасти репутацию, накормить Президентов и преодолеть миллион препятствий à la française…",
 "f-wd4524056": "Одинокий маленький человек делается заложником мечты о вещи, способной, по его мнению, полностью изменить его жалкое существование. Но сможет ли новая шинель сделать его счастливым.",
 "f-wd2665188": "Шестилетнего Ваню, воспитанника детдома, собирается усыновить итальянская семья — отсюда его прозвище «итальянец». Впереди — безоблачная жизнь под средиземноморским солнцем, но мальчик во что бы то ни стало хочет найти свою родную мать. Пройдя через предательство, ложь и обиды, он продолжает свой путь в поисках своей мамы...",
 "f-wd2994000": "Объявившие «священную войну» цивилизации террористы из «Ансар Аллах» готовят акцию, которая должна превратить Вечный город Рим в вечно мертвый город. Но мужество и героизм майора Смолина, самоотверженность и профессионализм журналистки Кэтрин Стоун, твердость духа чеченца Умара в сочетании с совместными действиями российских и западных спецслужб спасают заложников и мир от угрозы чудовищного теракта. Водоворот событий не оставляет героям фильма выбора: им остается только побеждать…",
 "f-wd2290357": "Эта история рассказывает об идеальном союзе — о любви и глубокой привязанности между матерью и сыном. Кажется, что эти двое одни на всей земле, нет ни быта, ни суеты, нет вообще ничего лишнего, а есть только деревянный дом за городом, в котором тихо живут тяжело больная мать и любящий сын.",
 "f-wd1964422": "Рассказ о жизни и творческой деятельности талантливого русского ученого-преобразователя природы — Ивана Владимировича Мичурина.",
 "f-wd4409920": "В Малиновке все ждут, устав от перестрелок гражданской войны, свадьбы пастуха Андрейки с Яринкой. Но банда атамана Грициана нападает на чудную деревню. Испуганная невеста убегает в лес, где засели красные, ждущие случая ударить по белым! Яринка взывает о помощи, и командир отряда разрабатывает план освобождения наших. Для этого Яринка должна придуриться и сыграть свадьбу с атаманом. А пока гости пили-пели, красноармейцы показали всю свою смётку и смелость. В оперетке не каждый сыграет и спляшет. А те артисты ещё как умели.",
 "f-wd1965544": "Спартак Молодцов — человек предельно аккуратный, непримиримый к любому беспорядку. Обнаружив однажды оборванный провод высоковольтной линии, он, разумеется, не мог пройти мимо. Но, как известно, «ни одно доброе дело не остаётся безнаказанным»...",
 "f-wd4308467": "Фильм рассказывает о великом русском композиторе Модесте Петровиче Мусоргском, его сотрудничестве с «Могучей кучкой» и первой постановке на сцене Мариинского театра оперы «Борис Годунов».",
 "f-wd4462912": "Какие они минуты счастья? Конечно, разные. Но есть среди них и такие: сидит в такси женщина и поет. Вернее, старательно, не очень умело выводит пронзительную мелодию: «... Опустела без тебя земля, как мне несколько часов прожить.» Странное иногда случается в жизни. Встретились два человека - симпатичная замужняя деревенская женщина, мать двоих детей приехавшая в Москву продавать домашнюю ветчину, и московский шофер, человек немолодой и далеко несловоохотливый.",
 "f-wd4195557": "Продолжение фильма «Солдат Иван Бровкин». После демобилизации Иван Бровкин гостил дома недолго. Вместе со своими друзьями он решил поехать на целину. А Любаша, не согласившись ехать в далекую землю, снова осталась ждать своего Ивана, который вместе со всеми преодолевал трудности, а вскоре стал бригадиром трактористов, ударником труда. Мать Ивана переехала к сыну, которому друзья-целинники построили новый дом. Сюда же приехал и Захар Силыч к своей Полине. За свой труд Иван Бровкин был награжден Орденом Трудового Красного Знамени. Теперь он приехал свататься к своей Любаше. Ее родители уже не возражали. После свадьбы молодые люди уехали на целину, чтобы продолжить освоение целинных земель.",
 "f-wd4458496": "Канун первой мировой войны. Казаки одной из донских станиц уходят в лагерь на военные сборы. Среди них Степан, муж молодой казачки Аксиньи. Проводив нелюбимого мужа, Аксинья сближается с Григорием, сыном казака Пантелея Мелихова. Старик, узнав о связи сына с чужой женой, решает остепенить его и женит на дочери богатого казака Коршунова Наталье. Но женитьба не смогла заглушить любви Григория к Аксинье...",
 "f-wd905466": "Одиннадцатилетняя Анна плохо контактирует с окружающими и от того чувствует себя одинокой и никем не понятой. Однажды она обнаруживает, что нарисованный ей домик, начинает оживать в каждом ее сне, и что она способна влиять на ход собственных сновидений, дополняя свой рисунок.\r Поняв это Анна через несколько дней становится полноправной хозяйкой своей собственной страны, куда легко перенестись, стоит только закрыть глаза и заснуть. Позже девочка начинает замечать, что события реальные и «нарисованные» постепенно приходят в какое-то странное взаимодействие друг с другом. Рисунок начинает поглощать ее, контролировать ее мысли, и возможно, собирается ее погубить.\r Тонкая грань между реальностью и воображением размывается. Кошмар затягивает Анну в свою западню. Выберется ли она из своих страхов живой?",
 "f-wd7715695": "Герой фильма взяв семью в поход и не предполагал, что простая вылазка в лес с палатками и рыбацкими принадлежностями выльется в ужасные последствия. Очень скоро он понимает, что его семью преследует знаменитый Дьявол из Джерси — монстр, по слухам обитающий в местечке Pine Barrens, что расположено на юге Нью Джерси.",
 "f-wd27703270": "Его манеры, настойчивость и великолепное чувство юмора с первого взгляда покорили неприступную Диану. После свадьбы молодожены отправляются в путешествие, где Робин тяжело заболевает. И теперь только любовь способна подарить ему вторую жизнь…Фильм основан на реальной истории.",
 "f-wd30011713": "История Макса и Энни, которые вместе с другими парами каждую неделю устраивают так называемые «ночные игры». И вот однажды харизматичный брат Макса Брукс организовывает вечер по разгадыванию «убийственного» квеста с «ряжеными» головорезами и агентами ФБР. Получается, похищение Брукса в тот вечер — это розыгрыш… или нет?  В итоге, по мере того, как шестеро мега-азартных игроков пытаются решить заготовленные головоломки и выиграть, они начинают осознавать, что и «квест», и Брукс — совсем не такие, как кажутся. В течение всей этой суматошной ночи друзья не раз прыгают выше головы, пытаясь выпутаться из очередной передряги. В игре нет правил, за нее не начисляются очки, а игроки понятия не имеют, кому противостоят. Эта ночь может стать самой зажигательной в их жизни… или последней.",
 "f-wd18151084": "70-летний вдовец Бен Уитакер обнаруживает, что выход на пенсию — еще не конец. Пользуясь случаем, он становится старшим стажером в интернет-магазине модной одежды под руководством Джулс Остин.",
 "f-wd64590532": "Импульсивный детектив полиции Нью-Йорка Зик Бэнкс всю жизнь пытается вырваться из тени своего отца, прославленного ветерана правоохранительных органов. Однажды Бэнксу и его новому напарнику поручают расследование серии жестоких убийств, которые странным образом напоминают преступления прошлых лет. Так они оказываются в эпицентре зловещей игры, и цена проигрыша в ней — человеческая жизнь.",
 "f-wd4340438": "Два юнца избили рабочего и были справедливо наказаны: один получил условный срок, а другой попал в колонию. Но потерпевшего не покидает мысль о том, как теперь сложится судьба подростков. Он начинает регулярно ездить на свидания с заключенным в надежде достучаться до его сердца...",
 "f-wd55087665": "Путешествие на самую высокую точку мира? Что может быть круче! Так решает Лу, когда случайно находит огромное, но очень милое чудовище посреди шумного мегаполиса. Пусть их преследуют учёные из сверхсекретной лаборатории, зато её новый друг умеет смешить и творить чудеса. Лу уверена, что поможет дружелюбному йети вернуться домой — на Эверест.",
 "f-wd1320806": "Бен Карсон знавал времена и получше. Уже прошел почти год с тех пор как неуравновешенного детектива отстранили от работы в Полицейском управлении г. Нью-Йорка за убийство другого сотрудника спецслужбы, несчастный случай, который не только стоил ему работы, но и пробудил в нем тягу к алкоголю и агрессивность, из-за чего жена и дети отдалились от него, а сам он нашел пристанище на диване в квартире своей сестры в Куинс. Потеряв надежду вернуться к нормальной жизни и воссоединиться с семьей, Карсон нанимается на работу ночным сторожем выгоревших руин универмага “Mayflower”. То, что когда-то было символом процветания и роскоши, теперь медленно разрушается в темноте, как загнивающий корабль-призрак, разоренный гигантским пожаром, поглотившим множество невинных жизней. Когда Карсон обходит дозором свои владения, обугленные развалины универмага, он начинает замечать что-то зловещее в декоративных зеркалах, украшающих стены “Mayflower”.",
 "f-wd131428108": "Сотрудник розничной сети проникает в окружение артиста, стоящего на пороге славы. По мере того, как он сближается с подающей надежды музыкальной звездой, доступ и близость становятся вопросом жизни и смерти.",
 "f-wd427296": "В окрестностях небольшого городка падает самолёт, на борту которого чрезвычайно опасный вирус. Зараза попадает в водную систему города, люди один за другим «заболевают» и начинают яростно набрасываться на всех подряд. Военные оперативно запирают город на карантин, периодически отстреливая зараженных.",
 "f-wd21168538": "В центре сюжета Джек Ричер, отправившийся в Вирджинию, на место своей бывшей военной службы. Он встречается с женщиной, которая имела положение и вес в армии, однако как только они встретились — их арестовали. Причем Ричера обвинили в преступлении шестнадцатилетней давности, которое, разумеется тот не совершал.",
 "f-wd19689203": "В центре истории – девочка по имени Софи, которая не смогла заснуть до полуночи, и в окошко увидела огромного великана, который подходил к соседним домам и начинал дуть в окна спален. В полном соответствии со старинными поверьями и детскими страшилками, великан увидел Софи и унес к себе домой, в страну великанов.  Как оказалось, он в этой самой стране был единственным добрым великаном: действуя в обстановке строжайшей секретности, он коллекционировал хорошие сны, которые по ночам раздавал детям. Уши у него устроены таким образом, что он слышит, что и о чем снится ребятам, и никогда не позволяет им видеть кошмары.",
 "f-wd17144452": "«999» - код опасности американских полицейских, который подразумевает намеренное убийство стража порядка. Сюжет разворачивается вокруг компании коррумпированных копов, решившихся на крупное ограбление. Но ради того, чтобы выйти сухими из воды, им необходимо убить кого-то из своих.",
 "f-wd8074696": "Фильм рассказывает о короткой жизни московской школьницы Зои Космодемьянской, которая в начале Великой Отечественной войны стала партизанкой-диверсанткой и была казнена немцами в подмосковной деревне Петрищево в ноябре 1941 года. За подвиг была удостоена звания Героя Советского Союза (посмертно)...",
 "f-wd14918344": "1941 год. Британская разведка безуспешно бьется над расшифровкой кода шифровальной машины «Энигма», разработанной немцами. Для достижения результатов наняты лучшие специалисты в области дешифровки, среди которых математик Алан Тьюринг — ученый блестящий, но не от мира сего. Добиться расположения коллег ему поможет Джоан Кларк (Кира Найтли) — единственная девушка, оказавшаяся в мужской команде, работающей над «Энигмой». Они с Аланом даже успеют обручиться, поскольку беспредельно уважают друг друга, но до свадьбы дело не дойдет. Тьюринг не хочет мучить девушку, поскольку не в силах пойти против своей природы: он гей, а геев в Великобритании преследовали по закону.",
 "f-wd121515216": "После событий первого фильма, Винни-Пух и Пятак больше не могут продолжать охотиться в Стоакровомом лесу. Очередное предательство Кристофера Робина, раскрывшего миру их существование, ставит под угрозу не только их дом, но и жизни. Вот только звери больше не намерены прятаться в тени и вместе с друзьями Совенком и Тигрой, отправляются в город, чтобы навести в нем свои кровавые порядки.",
 "f-wd26970": "Темная, пустынная лента шоссе змеей протянулась по безлюдному ландшафту средней Америки. Эта дорога живет своей жизнью, по своим правилам и законам, и если ты осмелился совершить по ней путешествие, то неплохо бы эти законы выучить наизусть.  Герои фильма попадают в жуткую переделку, когда Фулер уговаривает младшего брата Льюиса установить в машине старый радиопередатчик.  Для него это лишь «клевая» антикварная диковинка, с помощью которой можно позволить себе небольшой розыгрыш. Теперь ребятам придется своей кровью расплачиваться за поступок, на который способен каждый из нас…",
 "f-wd144414": "Моника Риверс — владелица небольшого передвижного цирка. Когда в ее цирке начинает происходить серия загадочных убийств, возникает вопрос: будет ли Моника следующей жертвой неизвестного маньяка или за всем этим стоит она сама, нуждающаяся в рекламе.",
 "f-wd18359358": "Лабиринт пройден, но Томасу, Терезе, Минхо и прочим глэйдерам не приходится расслабляться. Таинственное руководство ПОРОКА — секретной организации, устроившей гонки на выживание — назначает ребятам новые, смертельно опасные испытания. На сей раз их ждет переход по раскаленной пустыне и встреча с жертвами неизлечимой болезни, которые отличаются буйным нравом и непредсказуемым поведением.",
 "f-wd30302806": "Обычная игра «Правда или действие» превращается в жестокую гонку со смертью, когда к процессу подключается нечто сверхъестественное. Стоит кому-то из участников соврать или не выполнить положенное действие, его ждет жестокая расправа. Кто в итоге сможет выйти победителем в жестокой игре?",
 "f-wd34220038": "1987 год. Скрываясь от преследования, Бамблби прибывает на Землю, где тут же сталкивается с военными. В результате стычки с землянами и десептиконом, Бамблби лишается голосового модуля, повреждает память и перед отключкой сканирует стоящий неподалёку Фольксваген Жук. Через некоторое время девушка по имени Чарли находит его на автомобильной свалке в калифорнийском городке и получает в качестве подарка на 18-летие. Закатив машину в свой гараж, Чарли с удивлением обнаруживает, что ей достался не простой жёлтый Фольксваген Жук.",
 "f-wd13562643": "Бывший агент ЦРУ, пожилой афроамериканец Роберт Макколл, решил начать жизнь заново, оставить непростое прошлое и смотреть в будущее, как и обещал покойной жене. Он уже нашёл обычную работу продавца в магазине. Однажды Макколл вступается за юную проститутку Тери, с которой болтал в местной закусочной и которая находится под контролем русской мафии. Макколл прекращает свою добровольную отставку и начинает самостоятельные поиски правосудия. Все, кто страдает от криминальных авторитетов, коррумпированных чиновников и не может найти помощи у государства, находят помощь в лице Макколла. Он поможет. Потому что он — великий уравнитель.",
 "f-wd596965": "За убийство, которое он не совершал, взломщик сейфов Анри Шарьер приговорен к пожизненному заключению и отправлен на каторгу. Прозванный «Мотыльком» из-за того, что на его груди вытатуирован этот символ свободы, Анри совершает несколько попыток побега. В наказание власти надолго сажают его в карцер, а затем отправляют во Французскую Гвиану на остров Дьявола, со всех сторон окруженный океаном.  Из этой самой страшной каторжной тюрьмы не удавалось бежать ни одному заключенному. Но ничто не может заставить Анри пасть духом и сломить его решимость вырваться на волю…",
 "f-wd382289": "На передовых позициях межгалактической войны Добра и Зла — снова любимые герои: Анакин Скайуокер, Оби-Ван Кеноби и Падме Амидала, а также присоединившийся к ним падаван Анакина, Асока. Противостоящие им злодеи — Палпатин, граф Дуку и генерал Гривус — вынашивают план захвата Галактики. Начинается последняя схватка, и судьбы Вселенной вверены рыцарям-джедаям. Их подвиги станут самыми яркими эпизодами масштабных битв и подарят множество удивительных открытий.",
 "f-wd681962": "Многие сотрудники британской разведки догадывались, что в ее руководстве давно засел «крот», работающий на Россию. Но те, кто отваживался об этом заявлять открыто, почему-то оказывались в отставке. Остальные предпочитали помалкивать. Но подтверждение существования русского агента пришло с совсем неожиданной стороны. Начинается тайное расследование, возглавляемое находящимся в отставке Джорджем Смайли. И никто, включая высшее руководство разведки, не должен догадаться, что на крота снова объявлена охота.",
 "f-wd1048166": "Каспер, маленькое дружелюбное привидение, не желает походить на своих хулиганствующих собратьев. Его дружба с девочкой-подростком Кэт помогает ей и ее отцу, доктору Харви, справиться с опасностями, поджидающими их в населенном призраками доме.",
 "f-wd35160593": "Когда все агенты секретной службы Её Величества внезапно выходят из строя, в игру вступает запасной вариант. Образец английского стиля и любимец роковых красоток; король безвыходных ситуаций и хранитель аналоговых традиций в цифровом мире, агент Джонни Инглиш – боль и гордость британской разведки. Этому парню есть что взбалтывать, и он взболтает не по-детски.",
 "f-wd753517": "Нью-йоркский писатель Эдди, желая преодолеть чёрную полосу в жизни, принимает засекреченный препарат под названием NZT. Таблетка выводит мозг парня на работу в нереальной мощности. Этот творческий наркотик меняет всю жизнь Эдди, за короткий срок он зарабатывает кучу денег, но скоро начинает страдать от зловещих побочных эффектов препарата. А когда пытается найти других NZT-гениев, чтобы понять, как можно справиться с этим пристрастием, он узнает страшную правду…",
 "f-wd498867": "Зверски изнасилована десятилетняя девочка. Отец девочки расстреливает подонков.Ему грозит газовая камера. Сможет ли блестящий адвокат, не проигравший ни одного дела, добиться признания невиновности своего клиента?",
 "f-wd4310958": "После победы на турнире по киберспорту команде геймеров вручают диски с только что разработанной игрой. Запустив игру, каждый из них подвергается воздействию, переводящему их игровые способности в реальные. Некие \"авторитетные\" структуры путем шантажа, обмана и подкупа предлагают геймерам \"работу\". Перед геймерами стоит задача либо найти тираж и уничтожить его, либо, создав и возглавив целую армию геймеров, диктовать преступникам свою волю...",
 "f-wd44506078": "2071 год. Галактические войны разрушили Луну и изменили климат на Земле. Москва — в тропических лесах, а Нью-Йорк покрылся льдом. Над Москвой возвышается огромный инопланетный корабль — это стадион, на котором проходят зрелищные межгалактические соревнования по космоболу — игре, объединившей в себе спорт и гладиаторские бои. За матчами следит вся галактика. Играть в космобол могут только атлеты. Именно так называют тех, кто наделён необыкновенными способностями и может ими управлять. Космобол обожают все, кроме Антона, самого обычного парня, который всего лишь мечтает найти работу, чтобы помочь семье. Но однажды у него обнаруживают сверхспособности, и принимают в сборную. Теперь он игрок в космобол. Антон ещё не подозревает о том, какая роль уготована ему судьбой в этом матче, и что финальная игра станет сражением за Землю.",
 "f-wd111605536": "Еще при жизни Петр Ильич Чайковский считался величайшим композитором своего времени. Его творчеством восхищались как в России, так и далеко за ее пределами. Однако мужчину всегда окружали грязные слухи, не дававшие ему жить спокойной жизнью. И однажды Чайковский осознает, что больше так продолжаться не может. Чтобы избавиться от молвы, композитор решает стать женатым человеком. Однако после свадьбы ситуация лишь усугубляется. На Петра обрушивается серьезнейший душевный кризис, грозящий отобрать всякие надежды на продолжение карьеры. Понимая, что решение о женитьбе было ошибочным, творец расстается с супругой и вновь сталкивается с пренебрежительным отношением окружающих. А вот его бывшая жена и вовсе начинает медленно, но верно сходить с ума, с каждым днем теряя даже самые ничтожные шансы на обретение личного счастья.",
 "f-wd3840681": "Геолог Виктор, оказывающийся по пути домой в неком провинциальном городке, встречает там девушку Лену. Между ними происходит, что называется, любовь с первого взгляда. Виктор обещает увезти Лену к себе домой, где их ждет долгая счастливая жизнь. Но на следующий день все обстоит совершенно иначе. Это не Виктор становится подлецом — меняются обстоятельства. Его утренние чувства уже совсем не такие, как вечерние. Утро в очередной раз доказывает, что оно мудренее вечера. Лена прекрасно понимает, что чудесный незнакомец, собравшийся увезти ее из опостылевшего города — нарушение всех жизненных правил. И когда наутро сказочный герой превращается в обычного хмурого, неразговорчивого мужика, она внутренне готова к такому повороту событий…",
 "f-wd4030205": "Морпех - первогодок Саня Ежов оказывается среди пиратов на захваченном танкере. Он знает - товарищи не бросят. Ему нужно выжить и помочь своим, когда начнется штурм. Фильм основан на реальных событиях 5 мая 2010 года, когда морские пехотинцы БПК «Маршал Шапошников» освободили захваченный в водах Аденского залива российский танкер «Московский университет». У них было только 22 минуты без права на ошибку...",
 "f-wd24611747": "Обычная, казалось бы, неделя из жизни ничем не примечательного школьника Коли Смирнова превращается в череду невероятных происшествий: Коля влюбляется в учительницу английского, кто-то поджигает школьную пристройку с новыми компьютерами, а папа Коли заявляет семье о необходимости отказа от ночного сна, из-за чего никому в доме не удается выспаться и собраться с мыслями. Вдобавок в самого Колю влюбляется дочка директора, старшеклассница Ксюша, решившая, что это именно он поджёг школу. Остаётся всего несколько дней до субботнего праздника школы, где должны встретиться все действующие лица этого водоворота событий, и теперь хорошему мальчику Коле необходимо успеть разобраться со своей личной жизнью, расследовать поджог и наладить взаимоотношения с родителями.",
 "f-wd77840318": "Близится новый год, и сотрудники отдела полиции Барвихи планируют праздновать его за городом в тёплой компании старых друзей и коллег. Но непредвиденные обстоятельства в лице преступников, ограбивших крупное ювелирное предприятие, ставят праздник под угрозу. Смогут ли рублёвские полицейские вернуть украденные драгоценные камни стоимостью миллионы долларов и спасти свой праздник до того, как часы пробьют полночь?",
 "f-wd4096414": "Фильм является идейным продолжением жизни героев телесериала «Бригада». Однако акцент смещен в историю сына Александра Белова — Ивана. Это Кино о современной России. О том, что у всех на устах: политике, коррупции, цинизме крупного бизнеса и спецслужб. О новом поколении, которое, узнав правду о нечистом бизнесе родителей, не идет по их стопам, а выбирает новый путь. Для них дороги понятия чести, любви и Родины. Герой, комфортно живший за границей, тем не менее, выбирает Россию (в отличие от сериала) и остается жить в ней, надеясь привнести эти идеалы в жизнь своих близких и страны в целом.",
 "f-wd1251094": "Когда Самира и Кунала выгоняют из съемной квартиры, потому что хозяйка не хочет, чтобы они приставали к ее молодой и сексуальной племяннице Нехе, они идут по плану «Г» — притворяются геями, чтобы получить квартиру. Все хорошо, пока они не знакомятся с обворожительной сиреной Нехой, и не начинается самое большое испытание их дружбы. Тем более, что есть еще третий — босс Нехи Абхиманью…",
 "f-wd258979": "Викторианская Англия. После восьми лет, проведенных в пансионе для бедных девочек, сирота Джейн Эйр получает место гувернантки в Торнфилде - вотчине Эдварда Ферфакса Рочестера. Хозяин поместья редко наведывается в родные края, а в его отсутствие Джейн должна присматривать за восьмилетней Адель Варанс - воспитанницей аристократа. И вот однажды Рочестер возвращается. Так начинается одна из самых известных романтических историй в европейской литературе и мировом кино…",
 "f-wd785406": "Они познакомились, когда ей было шесть, а ему — тридцать шесть. Они поженились, когда ей было двадцать три, а ему тридцать один. Потому что Генри страдает редким генетическим заболеванием — синдромом перемещения во времени; его исчезновения из жизни Клэр непредсказуемы, появления — комичны, травматичны и трагичны одновременно.",
 "f-wd117830073": "Чемпионы Земного царства вместе с Джонни Кейджем вступают в схватку друг с другом, чтобы предотвратить тёмное правление Шао Кана.",
 "f-wd4029298": "1812 год. Накануне решающей битвы при Бородино тайный агент Наполеона похищает план сражения. Об этом становится известно Кутузову, и он посылает на перехват своих лучших улан. Путь их лежит в Польшу, где разворачивается бурный роман Наполеона с графиней Валевской…",
 "f-wd17582609": "В провинциальном городке на местном ТВ прозябают два друга — Ширяев и Молоток, и их коллега — красавица Надя. Все трое мечтают разбогатеть и стать столичными звездами. Неожиданно им в голову приходит идея: устроить реалити-шоу, участники которого должны отыскать золото Колчака. Одержимые жадностью герои шоу пускаются в гонку за кладом на самолетах, поездах и автомобилях. В пути их ждут сумасшедшие приключения, и все они еще не знают главного секрета…",
 "f-wd4251624": "Актеры Серега, Женечка и Эндрю, устав ждать, когда удача отыщет на карте их уездный город, приезжают покорять Москву. Выступление на корпоративе у Мафии производит такой фурор, что Босс Мафии умирает от смеха. Спасаясь от Мафии, Киллеров и Спецслужб, друзьям приходится угнать старый автомобиль. Их ждут неожиданные встречи и опасные приключения. Ведь теперь они — не просто ЛОпуХИ, а настоящая Банда Бандитов…",
 "f-wd2093457": "Дождливый летний вечер. В строящийся в подвале бывшего бомбоубежища ночной клуб «Фобос» съезжаются молодые люди, у каждого на это есть своя причина. Ребята из разных слоев общества: кто-то учится, кто-то бездельничает, кто-то трудится на этой стройке, а кто-то прожигает папины деньги. Поначалу встреча не предвещает ничего плохого. Однако происходит аварийное закрытие дверей бомбоубежища, и свет в помещении гаснет. Невольные узники не осознают всей опасности происшедшего — они шутят, пугают друг друга, но вскоре выясняется, что их мобильные телефоны вне зоны действия сети, а о своем намерении поехать в клуб они никому не сообщили…",
 "f-wd132200341": "Линда Лиддл, сотрудница отдела стратегического развития, справедливо считает себя очень полезной сотрудницей и рассчитывает на повышение. Вот только в офисе она всех раздражает, и когда после смерти пожилого президента компании это место занимает его сын Брэдли, обещанная Линде должность уходит другому. Вскоре делегация фирмы отправляется в командировку в Бангкок, самолёт терпит крушение, и единственными выжившими на небольшом тайском острове оказываются Линда и Брэдли. Будучи фанаткой шоу о выживании, женщина сразу берёт ситуацию в свои руки.",
 "f-wd9125658": "Действие этой ленты разворачивается до событий, описанных в «Молчании ягнят» и до появления Клариссы Старлинг. Мы знакомимся с человеком, поймавшим Ганнибала Лектора, — специальным агентом ФБР Уиллом Грэмом.\r После ареста Лектора, который едва не стоил Грэму жизни, Уилл уходит со службы в Бюро. Однако, появление нового жуткого серийного убийцы заставляет Грэма вернуться на службу. Этот безжалостный монстр, которого пресса уже окрестила «Зубной Феей», ночами вырезает целые семейства.",
 "f-wd478748": "Айрис Симпкинс, автор популярной свадебной колонки в лондонской «Daily Telegraph», живет в очаровательном коттедже в английской провинции. Она влюблена в мужчину, который любит другую. Далеко от нее в Южной Калифорнии живет Аманда Вудс, владелица процветающего рекламного агентства, занимающегося созданием роликов для фильмов. Она вдруг обнаруживает, что любимый человек ей изменяет.Две незнакомые друг с другом женщины, живущие на расстоянии 10 000 километров друг от друга, оказываются в сходной ситуации. И они находят друг друга. В Интернете, на сайте обмена жильем на время отпуска. Перед Рождеством Айрис и Аманда решают отдохнуть от своих проблем, договорившись поменяться континентами и пожить друг у друга в течение двух недель. Айрис переезжает в дом Аманды в солнечной Калифорнии, а Аманда приезжает в засыпанную снегом английскую провинцию…",
 "f-wd80204": "Встречая приехавшую из Петербурга мать, молодой блистательный офицер граф Вронский знакомится с женой влиятельного петербургского чиновника Анной Карениной. Огонь страсти вспыхивает мгновенно, но их любовь шокирует высшее общество. В мире, где правят предрассудки и стереотипы, ей придётся сделать поистине непростой выбор между семьёй и всепоглощающей страстью…",
 "f-wd127118132": "Дева, бывший главарь бандитской группировки, использует старинные золотые часы, чтобы снова собрать старую банду и основать новую криминальную империю. Им движут амбиции и месть, ведь с юности его преследовала несправедливость.",
 "f-wd126954881": "В оживленном городе Калькутта Рухан, ясновидящий, умеющий изгонять нечистую силу, на самом деле является хитрым мошенником. Если во время представления что-то идет не так, он скрывает свою некомпетентность, обвиняя несуществующих призраков. Когда принцесса Мира обращается к нему за помощью, чтобы избавить замок своей семьи от печально известного духа, Рухан чует возможность поживиться. Однако, по мере того как он углубляется в темную историю замка, события принимают странный оборот.",
 "f-wd125918989": "Во время круиза на роскошном лайнере происходит загадочное убийство. Каждый пассажир становится подозреваемым, а двое из них берут на себя роль детективов, пытаясь раскрыть преступление.",
 "f-wd125453590": "Бедный кассир, работающий в банке, ввязывается в рискованную инвестиционную схему и вскоре оказывается втянутым в мрачный мир отмывания денег.",
 "f-wd123169099": "Вирадж - известный модный фотограф с собственной студией в Мумбаи и с шестилетней дочерью Махи, страдающей муковисцидозом. Интересуясь своей матерью, Махи получает от отца обещание рассказать свою историю, если она станет лучшей в классе. Вирадж, как может, пытается скрыть правду от дочери. Но наступает момент, когда пора рассказать историю их отношений и того, что произошло...",
 "f-wd125295778": "Крутой, но непокорный полицейский оказывается в паутине обмана и предательства во время расследования громкого дела.",
 "f-wd115010349": "У 40-летней матери-одиночки, неожиданно завязывается роман с 24-летним солистом самой популярной мужской группы на планете.",
 "f-wd126918438": "Сотрудник налоговой службы Индии Амай Патнаик за время своей работы изъял более 4200 кроров во время своих рейдов, и теперь расследует очередное преступление, совершённое «белым воротничком».",
 "f-wd118383015": "Главный герой фильма - Аналисан \"Иса\", бывший солдат Британско-Индийской армии, известный как Капитан Миллер, становится символом сопротивления колониальному режиму. После того как Миллер становится свидетелем безжалостного акта насилия, совершенного британскими колонизаторами, он решает отказаться от своего прошлого и бросить вызов системе. Его действия превращаются в серию смелых и рискованных операций, включая ограбления, нападения и зрелищные побеги, направленные на подрыв власти британцев и поддержку угнетенного народа Индии.",
 "f-wd124218653": "1952 год. Мальчик Мурликант Петкар живёт с родителями и старшим братом в маленькой деревне. Однажды тайком от отца он с братом отправляется на вокзал и с воодушевлением наблюдает, как толпа приветствует индийского борца, который стал бронзовым медалистом Олимпийских игр в Хельсинки. С этого момента Мурликант начинает мечтать лишь об одном — стать известным спортсменом и завоевать золотую медаль на Олимпиаде.",
 "f-wd126948105": "Во время подготовки к решающему сражению с демонами члены Корпуса и столпы проходят изнурительную программу — Тренировку Хашира. Но внезапно сам Музан Кибуцудзи появляется в особняке Убуяшики. Когда глава Корпуса оказывается в смертельной опасности, Танджиро и Хашира спешат на помощь, но Музан втягивает их в таинственное пространство — замок Бесконечности, логово демонов. Так начинается финальное сражение между охотниками на демонов и силами зла.",
 "f-wd124656178": "Три стюардессы индийских авиалиний, из раза в раз оказывающиеся в неожиданных для себя ситуациях, в итоге решают вместе пуститься «во все тяжкие».",
 "f-wd125613310": "Бывший гангстер Каали давно завязал с криминалом, но когда его старый босс Рави просит помочь в войне с коррумпированным полицейским Арунагири, прошлое настигает его. После провала покушения Каали оказывается между двух огней: с одной стороны — мстительный Арунагири, с другой — обезумевший от жажды крови сын Рави, Каннан.",
 "f-wd56274037": "В течение четырех дней во время ежегодного праздника Пуджи по улицам бродит дух невесты. Он зовет молодых мужчин, и если те оборачиваются, то воспринимает это как их согласие быть с ней. Вики - талантливый портной, и он не верит в этот миф. В первый день Пуджи таинственная молодая девушка приближается к нему и проявляет романтический интерес, Вики влюбляется в нее. Парень рассказывает обо всем своим друзьям Яну и Битту. Последний анализирует ситуацию и понимает, что девушка Вики может духом невесты.",
 "f-wd127630083": "Группа друзей за совместным ужином раскрывает секреты друг друга.",
 "f-wd3292215": "Эта история основана на реальных событиях, произошедших во время битвы при Лонгевале в Раджастане (Восточный театр боевых действий) во время Индо-Пакистанской войны 1971 года и Освободительной Войны в Бангладеш.",
 "f-wd30090770": "В Индии один неизвестный украл крупную сумму денег, используя для этого случайных людей, не подозревающих, во что их втянули. Раскрыть преступление поручают Ашоку Чакраварти, офицеру полиции под прикрытием. Но вскоре герои и злодеи меняются местами.",
 "f-wd67200799": "Случайная встреча между двумя незнакомцами, Руханом и Ритом, заставляет их посетить родной город Рита в Раджастхане, где они раскрывают старый секрет, который вызывает панику.",
 "f-wd14948561": "Действие фильма начинается в Чикаго в 1990 году, когда Сахир был ребёнком и рос в цирке своего отца. Но компания увязла в долгах и банкиры были непреклонны. Отец Сахира от отчаяния застрелился. С тех пор Сахир мечтает отомстить за смерть своего отца, и для этого он планирует ограбить тот самый банк.",
 "f-wd1418833": "Лесбийская любовь в Индии — как это? Ашок управляет семейным бизнесом (еда на вынос, а также видеопрокат). У него большая семья: его жена Рада, брат Джатин, их мать Биджи, их слуга Мунду. Все они живут вместе. Джатин по настоянию матери и брата соглашается жениться на красавице Сите, хотя на самом деле он влюблен в другую. На первый взгляд перед вами идиллия, счастливая семья из среднего класса. Но оба брака несчастны: Ашок ударился в религию, его брат открыто встречается с любовницей, и случается неизбежное: обе жены братьев, Рада и Сита, влюбляются друг в друга!",
 "f-wd16253210": "Описание: Жил-был один простой парень, по имени Прем. Он жил себе жил, да ни о чем не тужил. Играл в спектаклях, зарабатывая деньги вместе со своим закадычным другом для благотворительного фонда, которым управляла любовь всей его жизни - принцесса Майтхили Деви. Наш Прем мечтал, что однажды он сам лично вручит королевской особе все сборы от пожертвований и признается в своих чувствах.",
 "f-wd219396": "Видья прилетает из Лондона в Калькутту, разыскивая своего без вести пропавшего мужа. Женщина находится на седьмом месяце беременности, но это не мешает ей с энергией взяться за поиски. Однако все люди, которые, по идее, так или иначе должны быть связаны с ее мужем, в один голос уверяют героиню, что никогда и слыхом не слыхивали о ее супруге. Все пытаются убедить ее, что ее мужа попросту не существует. Мало-помалу героиня осознает, что весь город погряз во лжи…",
 "f-wd3595073": "Жизнь Виджая полностью рушится, когда злодей и наркоторговец становится причиной смерти отца. Виджай уезжает в Мумбаи со своей беременной матерью с одной только мыслью — вернуться в родную деревню и вернуть славу имени своего отца.",
 "f-wd1427204": "В провинциальном городке Васко все внимание горожан привлечено к соперничеству двух молодежных группировок. Эти группировки возглавляют Макс и Пракаш. У Макса есть сестра-двойняшка Ширли, которую он очень любит и заботливо опекает. К Пракашу из Бомбея приезжает брат Рахул, который, увидев Ширли, с первого взгляда влюбляется в нее. Через некоторое время и Ширли отвечает ему взаимностью. Однако у молодых людей не много шансов соединить свои судьбы, так как Макс и Пракаш ненавидят друг друга. Вскоре Рахул и Ширли лишаются и этих шансов, когда одна из разборок приводит к трагедии...",
 "f-wd17113531": "Девушка Лейла, страдающая церебральным параличом, уезжает из Индии на учебу в Нью-Йорк, где она неожиданно влюбляется. Так начинается волнующее путешествие самопознания.",
 "f-wd1248795": "Радж Матхур - молодой и амбициозный инженер с единственной целью в жизни - переехать в Бомбей и стать там знаменитостью. Он трудится изо всех сил, мечтая о больших зданиях и больших проектах. В Бомбее он встречает Джая, который становится ему хорошим другом, и влюбляется в Рену. Она находит ему место в строительной компании, в которой сама работает. Теперь карьера Раджа идет в гору. С успехом он приобретает новых друзей - встречает Саину, дочь его босса. Она показывает ему новую культуру, новый стиль жизни и влюбляется в него. Повлияет ли успех Раджа на его взаимоотношения с Рену?",
 "f-wd1423563": "Рахул обычный клерк в небольшом офисе. Он давно не равнодушен к прекрасной Симе, которая работает фотомоделью. Но Сима еще нравится и начальнику фирмы, в которой и работает Рахул. Начальник фирмы прекрасно знает о чувствах Рахула к девушке фотомодели. И однажды начальник предлагает Рахулу небольшую сделку: Рахул отказывается от Симы навсегда, а начальник в свою очередь сделает Рахула главой новой фирмы…",
 "f-wd855020": "Рассказ о взаимоотношениях между призраком умершего старика и мальчиком Банку. Семья приезжает жить на Виллу Натх в Гоа. Этот дом все обходят стороной из-за живущего там призрака. Бхутнатх — имя, которое дал призраку мальчик Банку (от Бхут — призрак, Натх — имя владельцев виллы). Банку не верит, что призраки существуют, поэтому не испугался, когда увидел страшного старика. Он решил, что это — ангел, и очень скоро они становятся друзьями. Прияншу Чаттерджи исполняет роль сына Бхутнатха, который должен помочь душе отца найти покой.",
 "f-wd30639027": "История об индийской национальной героине, символе сопротивления деспотизму британских колонизаторов, лидера княжества Джханси - Лакшми Баи (имя при рождении - Маникарника). В 1857 году женщина принимала активное участие в Сипайском восстании против жестокой политики англичан: возглавляла оборону Джханси от армии генерала Роуза и воевала во главе кавалерийского отряда.",
 "f-wd207494": "Касауни - маленький городок в предгорьях Гималаев. Как и вся страна, он охвачен пламенем народной борьбы за независимость. Но двое влюбленных позабыли обо всем на свете. Однако от действительности невозможно спрятаться, и мы становимся свидетелями увлекательной саги о людских радостях и горестях, о долге и чести, о борьбе за справедливость и конечно же о любви.",
 "f-wd3136560": "Вишам — младший сын влиятельного деревенского землевладельца —заминдара. В отличие от отца, который ради достижения своих цепей не гнушается нарушать закон, у Вишама нет вредных привычек. Он женат на Рукмани и хранит ей верность.  Вскоре в деревню приезжает новый учитель с женой Сушилой и однажды поздно, под конец ночи, Вишам видит как несколько человек насильно захватывают Сушилу и увозят ее прочь...",
 "f-wd128787041": "Ноа и Николас влюблены и счастливы, но это прекрасное чувство очень хрупко. Достаточно одной искры, чтобы пламя недоверия все разрушило. Смогут ли влюбленные преодолеть попытки родителей их разлучить? Удастся ли им сохранить чувства, несмотря на появление бывшей девушки Ника, новых друзей Ноа из колледжа и другие испытания?",
 "f-wd55621418": "После смерти одного известного политического лидера, десятки лет работавшего в штате Керала, начинается безжалостная и ожесточённая борьба за власть. В этой войне принимает участие несколько очень богатых преступников, которые когда-то давно решили пойти в политику. Существует пять возможных преемников, и каждый из них готов сделать всё возможное для того, чтобы занять кресло партийного лидера. Среди этих кандидатов особенно выделяется один. Его репутация и влияние могут позволить ему взобраться очень высоко, и, кажется, партийные деятели уже готовы его поддержать. Однако борьба за власть только начинается, и в её пылу будет сломало немало копий…",
 "f-wd123144591": "Ратнам, преданный помощник члена парламента Паннера Селвама, внезапно сталкивается с неожиданной опасностью, когда ему поручено сопровождать молодую женщину на собеседование в Веллор. Что должно было быть простой деловой поездкой, превращается в спасение жизни, когда группа хулиганов атакует девушку. Ратнам в последний момент вступает в действие, принимая на себя роль ее защитника. С каждым днем угрозы становятся все серьезнее, и Ратнам вынужден задаться вопросом: насколько далеко он готов зайти, чтобы защитить ее? Как долго он сможет удерживать свою защитную руку над ней в этой игре на выживание?",
 "f-wd7278417": "Главный герой, Кундан, живет в городе Варанаси в семье тамильского индуистского священника-брамина. С самого раннего детства он влюблен в Зою, девочку из мусульманской семьи, и изо всех сил пытается завоевать её сердце. Ему предстоит преодолеть множество препятствий: классовых, социальных, религиозных..",
 "f-wd48672795": "Нередко даже могущественных граждан могут обмануть. Избирательный процесс является всего лишь публичной манипуляцией, которая должна убеждать общественность в прозрачности проведения определенные процедур. Бизнесмен, который беспокоиться о будущем своей страны, возвращается в Индию, чтобы принять участие в народном волеизъявлении. Однако его ждет горькое разочарование, поскольку кто-то уже использовал за него право проголосовать. Решив разобраться с этой ситуацией, он оказывается меж двух коррумпированных политиков.",
 "f-wd104884250": "После замужества женщина изо всех сил старается стать покорной женой, которую ждут от нее муж и его семья. История следует за её путешествием, когда она меняется сама и, более того, меняет семью.",
 "f-wd29832413": "1985 год. Рангасталам — небольшая деревня в долине реки Годавари, где в течение 30 лет бессменно правил раз за разом побеждающий на сельских выборах президент Фаниндра Бхупати, который безжалостно захватывал у крестьян их урожаи и землю, используя государственные программы. В деревню из Дубая в отпуск к своей бедной семье приезжает хорошо образованный и благородный Кумар Бабу. Видя страдания односельчан, он при поддержке видного политика Дакшины Мурти выдвигает свою кандидатуру на очередных выборах против Бхупати.",
 "f-wd28753302": "В Ираке во время вооруженного конфликта между иракской армией и террористами ранен лидер террористов Абу Усман. Его доставляют в местный госпиталь и берут в заложники индийских и пакистанских медсестер. Кроме того, со дня на день должны казнить группу американских журналистов. Пока ушедший на покой секретный агент индийской спецслужбы Тигр где-то в швейцарских Альпах голыми руками расправляется со стаей волков, родине снова понадобилась его помощь. Американцы согласились совершить авиаудар через неделю, поэтому у Тигра и его команды есть только 7 дней, чтобы вызволить заложников. Да и Зоя не может остаться в стороне — теперь индийские и пакистанские спецслужбы будут работать вместе.",
 "f-wd531328": "Молодая женщина-репортер расследует загадочное суеверие о смертоносной видеокассете. В доме того, кто посмотрит ее, сначала раздается странный звонок по телефону, еще чуть позже его находят мертвым.После того, как, видимо, такой же смертью умирает ее племянница, репортерша решает взяться за расследование и сама смотрит злополучную кассету. Чуть позже в ее квартире раздается звонок…",
 "f-wd192022": "Известный сценарист и режиссёр попадает в страшную автокатастрофу, после которой необратимо слепнет. Он не может больше снимать кино, от него уходит женщина, которая была смыслом его жизни. Вместе со зрением он теряет всё. Смириться с трагедией своей жизни он сможет только спустя 14 лет, открыв душу своему молодому помощнику, которого он полюбил как сына.",
 "f-wd1640076": "Христос освобождается от оков и оказывается в современном городе, средоточии человеческих пороков, культа смерти и секса. Здесь он и попадает в таинственную эзотерическую школу магов. Там же оказываются и молодые развращенные жизнью персонажи со всей Солнечной системы. Гуру и его ученики отправляются к Священной горе, где живут девять мудрецов, знающих секрет бессмертия…",
 "f-wd1544046": "Мать молодого человека Хосе не хочет его свадьбы с Сильвией — дочерью местной проститутки. Правда мама еще не знает, что Сильвия беременна от ее сына. А когда узнает об этом, то нанимает молодого красавца Рауля, который работает на колбасном складе и мечтает быть тореадором.  По ее замыслу Сильвия должна влюбиться в него, а соперник — ее сын будет лишним. Но события принимают совершенно непредсказуемый оборот и приводят к удивительным последствиям для всех.",
 "f-wd1077915": "Фильм повествует о развитии дзюдо в Японии конца 19-го века. В центре сюжета — молодой человек Сугата Сансиро, прибывший в большой город с целью изучать боевые искусства. Сначала он попадает в школу джиу-джитсу, но после того, как видит, что его новый наставник устраивает на своего конкурента — легендарного учителя дзюдо Сюгоро Яно подлую засаду и с позором оказывается повергнут им, Сугата упрашивает Яно взять его в ученики.  Однако, путь воина, тернист и сложен не только своими физическими нагрузками, но и твёрдым моральным кодексом, подчинения которому требует Сюгоро Яно от своих учеников. Однажды из-за юношеской горячности преступив его, Сугата прыгает в пруд, повинуясь повелению учителя: «Умри!», и проводит в ледяной воде целую ночь. На рассвете он видит, как над поверхностью воды распускается цветок лотоса…",
 "f-wd1278929": "Место действия — лагерь беженцев, а герои — курдские дети, брошенные на произвол судьбы, их родители погибли во время иракской оккупации. Но среди разрушения, страха и насилия дети остаются детьми.",
 "f-wd5196238": "Тита и Педро любят друг друга. Но мать Титы не дает согласия на их брак: по давней семейной традиции младшая дочь должна заботиться о матери до самой ее смерти. Чтобы быть рядом с любимой, Педро… решает жениться на ее сестре! Живя под одной крышей, влюбленные лишены даже возможности выражать свои истинные чувства друг к другу.  И Тита начинает выражать одолевающие ее эмоции при помощи экзотических блюд, подаваемых к семейному столу. Кто знает, к чему может привести эта скрытая любовь?",
 "f-wd668718": "Юлий Цезарь не на шутку разозлился на британцев, которые не только не сдавались римским войскам, но и неоднократно помогали в битвах свободолюбивым галлам. Выход один - война. Тем более что британцы воюют лишь пять дней в неделю, да и то с перерывом для чаепития. Хитрый Цезарь вновь забыл, что где-то поблизости, - всего лишь через пролив, - проживает доблестный Астерикс с друзьями. Только им известен секрет таинственного зелья... А то, что подходит для галлов, подойдёт и для британцев!",
 "f-wd107273994": "Фильм расскажет о битве при Чосинском водохранилище в 1950 году во время войны в Корее между китайскими народными добровольцами и силами ООН...",
 "f-wd814166": "1966 год. По заданию ОOН астронавты Глен и Фуджи отправляются исследовать Планету Х. Местные гуманоиды рассказывают астронавтам, что из-за постоянных нападений ужасного Монстра Зеро они вынуждены жить под землей. При очередном нападении астронавты признают в монстре Кинга Гидору. Откликнувшись на просьбу о помощи, c Земли на Планету X доставляют Годзиллу и Родана, где они с честью одерживают победу над монстром. Все бы хорошо, но на самом деле Годзилла и Родан понадобились аборигенам Планеты X совершенно для иной цели…",
 "f-wd948025": "Возвращаясь с любовником с загородного рандеву, супруга богатого промышленника сбивает на пустынном шоссе велосипедиста. Опасаясь разоблачения супружеской измены, она скрывается с места происшествия. Однако чувство вины и тревожные мысли о единственном свидетеле случившегося не оставляют ее.",
 "f-wd151784": "Действие этой семейной саги происходит в Китае в течение трёх десятилетий - в 1940-60 гг. Наследник уважаемой в городе семьи, Фу Гуй - заядлый игрок. Злоключения его семьи начинаются с того, что однажды он проигрывает свой дом…",
 "f-wd633073": "Долгие годы жители поражённого радиацией островка в Тихом океане поклонялись своему божеству — гигантской бабочке Мотре и заодно её огромному яйцу, из которого в своё время должна была вылупиться новая Мотра. Так продолжалось до тех пор, пока на остров не налетел тайфун, который смыл драгоценное яйцо в море и прибил к берегам Японии, где его выловила бригада рыбаков.  Мотра в сопровождении двух своих фей-хранительниц обратилась к людям с просьбой вернуть яйцо обратно, но получила отказ: находка уже попала в руки крупной корпорации, решившей превратить яйцо в прибыльный аттракцион для туристов. Впрочем, когда страну вновь начал терроризировать Годзилла, людям ничего не оставалось, кроме как признать свою ошибку и просить Мотру о защите.",
 "f-wd643847": "Трагическая смерть соседского мальчишки не кажется Смилле Ясперсон обычным несчастным случаем. Начав расследование, она интуитивно продвигается в верном направлении, вынуждая противника идти на крайние меры.  Став объектом преследования, но проявляя упорство, Смилла узнает цену причины, которая заставляет преступников убивать не задумываясь.",
 "f-wd105998990": "На глазах Д’Артаньяна похищают его возлюбленную Констанцию. Пока верные друзья, три королевских мушкетёра Атос, Портос и Арамис, сражаются на поле боя, Д’Артаньян вынужден объединить усилия с таинственной Миледи, чтобы спасти свою любимую. Но страшные тайны прошлого могут разрушить как новые союзы, так и старую дружбу.",
 "f-wd763615": "27 апреля 1940 года. В самом начале Второй мировой войны над Скандинавией происходит яростная битва двух самолетов — английского и немецкого. Немецкий «Хейнкель-111» отклонился от курса и заблудился после атаки на корабли ВМФ Великобритании. Английский истребитель осуществлял дежурное патрулирование воздушного пространства той части Норвегии, которая не была ещё оккупирована нацистской Германией. По стечению обстоятельств во время воздушного боя оба самолета выходят из строя, и пилоты с трудом приземляются на заснеженные озера Норвегии. Выжившие члены обоих экипажей во время метели набрели на охотничий домик (в реалии — через 4 часа), где и нашли себе пристанище. Немцы вооружены, поэтому берут в плен английский экипаж. Но в дальнейшем ситуация меняется. Пурга, глубокий снег, отсутствие пищи и помощи извне вынуждает их сотрудничать. Постепенно возникают взаимные симпатии, помогающие преодолеть трудности.",
 "f-wd1190863": "В небольшой горной деревушке тринадцатилетняя Вэй Миньчжи остается заменять школьного учителя Гао. Не очень довольный подобной заменой, Гао обещает Миньчжи десять юаней, если за время его отсутствия ни один из двадцати восьми учеников не оставит школу. Но именно это вскоре и происходит и Миньчжи отправляется на поиски своего подопечного в большой город...",
 "f-wd2131160": "В 1905 году Сунь Ятсен, собирается посетить Гонконг, чтобы обсудить планы революции и свержения династии Цин с товарищами из организации Тунмэнхой. Вдовствующая императрица Цыси, находящаяся у власти, посылает группу убийц во главе с Ян Сяого помешать Сунь Вэню. С другой стороны, Сунь Вэня защищают телохранители — рикши, уличные торговцы, бродяги, которых организовывает бизнесмен Ли Юйтан. Его сын Ли Чунгуан берет на себя роль двойника Сунь Вэня, чтобы отвлечь убийц от настоящего и дать ему возможность беспрепятственно провести встречу и покинуть Гонконг.",
 "f-wd1734874": "Молодой полицейский Тед, поступивший в спецподразделение полиции, получает первое задание. Во время расследования Тед узнает, что его братец Денни, непутевый толстяк и недотепа, оказался замешанным в торговле краденым. Спасение единственного родного человека становится главным заданием Теда.",
 "f-wd2399461": "Картина рассказывает о скитаниях по Ирану двух оставшихся без крова после бомбардировки учителей: один из них встречает детей, которые не желают учиться читать и писать, а другой — стариков в поисках родной земли…",
 "f-wd196103": "Филипп красив, богат и… одинок. Ида замужем, но ее супруг увлечен другой. Скоро они встретятся на свадьбе своих детей в одном из самых живописных городов мира -итальянском Сорренто. Знойные неаполитанские ночи, аромат лимонных деревьев и непередаваемая атмосфера праздника помогут вспомнить, что любовь — это все, что им нужно…",
 "f-wd260365": "Расставшись с женой, Андреас Винкельман уезжает на остров. Он ведет замкнутый образ жизни, пока случай не сводит его с соседями: архитектором Элисом, его супругой Эвой и их подругой Анной. Между ними складываются доверительные отношения, которые в скором времени перестают быть просто приятельскими. Эва становится любовницей Андреаса, а Анна – его новой подругой. Чем глубже связь Андреаса с женщинами, тем сложнее ему контролировать свои чувства и поступки...",
 "f-wd109387468": "Молодой учитель Самет заканчивает четыре года обязательного преподавания в деревенской школе в Анатолии. Он хочет найти работу в Стамбуле, однако все надежды рушат две ученицы, обвиняющие его и другого учителя в харассменте. Заново найти смысл жизни Самету помогает его коллега Нурей.",
 "f-wd13550796": "Посетители ночного клуба оказываются взятыми в заложники. Среди посетителей есть офицер полиции Вэнь Чжун и его непослушная дочь Мяомяо. Человек, удерживающий всех в заложниках — владелец клуба, который таким образом пытается добиться освобождения из тюрьмы одного преступника.",
 "f-wd221887": "Двое - мужчина и женщина - встречаются в Копенгагене, проводят вместе восхитительную ночь и затем отчаянно пытаются освободиться от рутины будней и рискуют всем ради возможности быть вместе…",
 "f-wd1218226": "Швеция, 1907 год. Мария влюбляется в Зигфрида и становится его женой. Свое раздражение и недовольство жизнью грубый и агрессивный Зигфрид предпочитает вымещать на жене и детях. Тяжелая и монотонная жизнь Марии изменяется, когда у женщины появляется маленькая тайна: в благотворительной лотерее она выигрывает диковину — аппарат для фотографических снимков.  Увлекшись фотографией и научившись снимать, Мария понимает, что помимо бесконечных домашних проблем существует и другой мир. Ее снимки — особенные. Горожане все чаще обращаются к ней с просьбой сделать семейные фотографии. Постепенно выясняется, что у Марии Ларссон настоящий талант фотографа! Но это совсем не нравится вернувшемуся с войны мужу…",
 "f-wd11394785": "Выгнанный из леса бомж стучится в дом, чтоб ему дали помыться и получает по шее. Женщина, решает ему помочь и впускает ночью к себе, в тайне от мужа. Но у бомжа созревает свой план мести.Со своими помощниками,он методично расправляется со всеми, кто встает у него на пути.",
 "f-wd660666": "Чтобы защитить страну от Годзиллы, если она вдруг опять нападет на Японию, ученые сконструировали Механическую Годзиллу — гигантского управляемого робота, наделенного всеми функциями, имеющимися у живого монстра.  В процессе создания робота были использованы полностью органические ткани организма монстра, выращенные искусственным образом из молекул ДНК Годзиллы, которые были сохранены с 1954 года, со времени первого нападения чудовища на Японию. Настоящий монстр Годзилла, конечно, просыпается и идет крушить японцев. Те выставляют на бой Меха-Годзиллу.",
 "f-wd1166240": "Ёсими и ее пятилетняя дочь Икуко живут в мрачном многоквартирном доме. Их преследуют как наваждение темная вода, капающая с потолка и сочащаяся из стен, и маленькая красная сумка, принадлежавшая девочке, которая пропала при загадочных обстоятельствах два года назад…",
 "f-wd110625579": "1999 год. Начав следить за мальчиком из школы по просьбе влюбленной подруги, девочка-подросток сама находит любовь.",
 "f-wd1589300": "Обыгранная сказка о Белоснежке, события которой развиваются в 1920 году в Севильи вокруг главной героини — женщины-тореадора.",
 "f-wd185884": "Технофетишист пытается увеличить свою ногу, вставив в нее кусок металла — труба длиной 30 сантиметров. И… он снимает бинты с ноги и его самодеятельная хирургия не удалась! Он кричит и убегает… Тем временем некий бизнесмен едет в машине и они встречаются в результате автокатастрофы. Это начало конца для нашего бизнесмена, который медленно превратится в груду металлолома.",
 "f-wd1533970": "В очередном фильме из далекой галактики на Землю прибывает кровожадное чудовище. Его цель — сеять смерть и разрушения. Робот «МЕГЕРА» не может остановить монстра. Тогда на помощь приходит Годзилла…",
 "f-wd28312": "Дядя Так прославлен своим искусством традиционной китайской медицины. Как эксперт боевых искусств он также обучает молодёжь мастерству самозащиты. Один из его учеников, Джонни, мечтает монополизировать преподавание кунг-фу в США. С этой целью он пытается убить Дядю Така. Джет, лучший ученик Дяди Така из Китая, приезжает в Лос-Анджелес чтобы разыскать своего учителя. Джонни и его люди не оставляют китайцев в покое, и тем приходится драться не на жизнь, а на смерть.",
 "f-wd709237": "Полицейский Вонг Вэй, приехав издалека, обнаруживает своего дядю, старшего полицейского офицера, убитым при загадочных обстоятельствах. Поскольку найденные улики не только не помогли делу, но ещё больше его запутали, Вонг решает сесть в тюрьму, чтобы, завоевав доверие заключенных, найти убийцу.  Однако дело принимает неожиданный оборот и Вонг оказывается замешанным в убийстве одного из тюремщиков, за что его приговаривают к смерти. Однако когда приговор вот-вот должен был быть приведён в исполнение, некто Вардер Тьен предлагает ему присоединиться к своему движению, несущему порядок и справедливость людям…",
 "f-wd563745": "Анна, молодая иностранная гувернантка, приезжает в загородный дом в скучном районе под Мадридом. Её встречает хозяйка дома Лучи, о трёх дочерях которой предстоит заботиться Ане. На семейном ужине Ана знакомится со своими эксцентричными нанимателями. В семье три брата средних лет (Хосе, Хуан и Фернандо), их больная мать, Лучи, жена Хуана, и их дочери. Ана начинает получать эротические письма, подписанные неизвестным обожателем, желающим быть с ней. Их доставляют из отдалённых мест, которые становятся всё ближе...",
 "f-wd566308": "В лесу, поблизости от дороги, была найдена убитая девочка. Полиция в растерянности, два похожих убийства, произошедших несколько лет назад, так и остались нераскрытыми. Уличный торговец Жакье сразу попадает под подозрение, несмотря на то, что это именно он указал полиции на местонахождение тела девочки. Но комиссар Маттей уверен в его невиновности. Он поклялся родителям убитой Гритли, что найдет убийцу.",
 "f-wd21857474": "Когда-то Рёта был известным писателем, но судьба сыграла с ним злую шутку – сейчас он незаметный частный сыщик, распутывающий мелкие будничные дела. Он многое потерял: похоронил отца, расстался с женой, забравшей при разводе сына. Но если его пожилая мать и красавица-бывшая как-то справились с этими трагедиями и живут дальше, то Рёта словно застрял в прошлом. Всё немногое, что он зарабатывает сыском, Рёта проигрывает, так что ему нечем даже платить алименты, не говоря уже о том, чтобы быть настоящим отцом для сына-школьника. Однако одна дождливая ночь может в корне изменить всю жизнь.",
 "f-wd18611423": "1953 год. Разгар Корейской войны. Маленький Ток-Су и его семья бегут из порта Хыннам. Однако отец и младшая сестра мальчика пропадают без вести во время отбытия корабля. Ток-су становится главой семьи. Годы идут, мальчик взрослеет, его единственное желание – найти пропавших отца и сестру. Фильм повествует об истории жизни Ток-су. О том, что он делал и, через что ему пришлось пройти ради обеспечения своей семьи. 60 лет жизни, смеха, радости, любви, горя и страдания…",
 "f-wd18684331": "У Чжин обладает одной очень интересной особенностью: утром, когда просыпается, он становится совершенно другим человеком. На протяжении долгого времени каждый день он живет новой жизнью. Но однажды У Чжин встречает И Су. Может она поможет ему побороть этот странный недуг? И как же будут строиться их отношения?",
 "f-wd1889303": "Ронал — самый нетипичный варвар на Земле. Его не интересуют ни битвы, ни завоевания, ни пиры. Больше всего на свете ему хочется, чтобы все просто оставили его в покое. Но судьба распоряжается иначе. Однажды злобный принц Вольказар, вождь враждебного племени, захватывает всех варваров в плен, чтобы принести их в жертву древним богам и обрести власть над миром. На свободе остается лишь Ронал. И теперь ему вместе с безалаберным бардом Алибером, мускулистой девой-воительницей Зандрой и эльфом-метросексуалом Эльриком предстоит пройти множество испытаний, чтобы освободить свой народ, обрести веру в себя и… найти любовь.",
 "f-wd1211197": "Высококлассный специалист по производству бумаги из вторсырья Брюно Давер был уволен два года назад. Он думал, что сможет легко это пережить. Но время шло, а Брюно так и не удалось забыть свою любимую работу. Тогда он решил, что хочет вновь вернуть ее и готов ради этого на все…",
 "f-wd779032": "О жизни бедной крестьянской семьи на острове, где нет воды, где есть только маленькие, отвоеванные у скал клочки земли. Чтобы прокормить семью, надо целыми днями поливать эти поля. И вот каждый день муж и жена отправляются за спасительной водой. На заре идут они за водой, в сумерках еще возят ее. Так продолжается изо дня в день, из года в год...",
 "f-wd1140945": "«Хронос» — это чудесное маленькое устройство, которое, сбежавший из Испании в Мексику гениальный алхимик Умберто Фальконелли, изобрел в 1536 году. Устройство, дарующее бессмертие… Правда, в 1937 году жизнь алхимика все-таки оборвалась в результате трагической случайности. Потому что «Хронос» обещал вечную жизнь при условии, что владелец будет собственной кровью питать его…  Имущество особняка, где жил алхимик, было продано с молотка. И вот однажды хозяин антикварного магазина старик Хесус Грис расковырял фигурку ангела и, обнаружив внутри странную коробочку, привел в действие ее заводной механизм… Так у «Хроноса» появился новый владелец, но не только ему был известен секрет бессмертия…",
 "f-wd483797": "Су-мин — воспитанник приюта, разрывающийся между работой на фабрике, учёбой в колледже и вечерней подработкой в качестве водителя по вызову. Однажды он довозит до дома молодого бизнесмена, и тот приглашает его к себе. Су-мин отказывается, но на следующий день они встречаются снова — на фабрике, в самый разгар увольнений. Су-мин отвергает помощь человека, который, по случайности, оказывается сыном владельца фабрики и пытается сохранить его рабочее место. Потерпев неудачу на другой работе, Су-мин устраивается в гей-бар, где обслуживает богатых клиентов.",
 "f-wd1170128": "Действие фильма происходит в рабочем квартале в шведском городе Мальмё в 1936 году. Молодой рабочий Андерс заканчивает свой первый роман, в котором описывает жизнь в своем квартале, и мечтает найти издателей в Стокгольме. Его отец, неудачливый коммивояжер, постепенно спивается. Во всех своих проблемах он обвиняет жену, мать Андерса, которая зарабатывает на жизнь мытьем подъездов. Андерса не устраивает положение, в котором находится его семья, он понимает, что нужно что-то менять. Но возможны ли перемены? Или побег из Вороньего квартала - единственный выход?..",
 "f-wd57905222": "После поражения от Ип Мана Чун Тинь-Чи решает исправиться и вести тихую мирную жизнь, но зло само нарывается на неприятности.",
 "f-wd909602": "Возвращение легендарного мастера Востока на поле битвы. На этот раз ему предстоит сражение не на турнире, а на просторах своей страны. Фонг Сай-Юк вступает в тайное общество «Красного Лотоса», которое борется за свержение правителя династии Манчу.  Но на пути к достижению цели он должен пройти не только через трупы врагов, но и через испытание своих чувств. Бой продолжается, и за каждым темным углом может таиться враг."
};
